package dev.ftb.mods.ftblibrary.client.config.gui;

import dev.ftb.mods.ftblibrary.client.gui.input.MouseButton;
import dev.ftb.mods.ftblibrary.client.gui.theme.Theme;
import dev.ftb.mods.ftblibrary.client.gui.widget.*;
import dev.ftb.mods.ftblibrary.config.manager.ConfigManagerClient;
import dev.ftb.mods.ftblibrary.icon.Icon;
import dev.ftb.mods.ftblibrary.icon.Icons;
import dev.ftb.mods.ftblibrary.net.EditConfigChoicePacket;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.network.chat.CommonComponents;
import net.minecraft.network.chat.Component;

public class ChooseConfigScreen extends BaseScreen {
    private static final int BTN_HEIGHT = 22;
    private final EditConfigChoicePacket message;

    private ChooseConfigScreen(EditConfigChoicePacket message) {
        this.message = message;
    }

    public static void open(EditConfigChoicePacket message) {
        new ChooseConfigScreen(message).openGui();
    }

    @Override
    public void addWidgets() {
        add(new TextField(this).setText(message.title()).addFlags(Theme.CENTERED | Theme.SHADOW));

        add(new TextButton(this, Component.translatable("ftblibrary.client_settings"), Icons.PLAYER,
                (widget, button) -> ConfigManagerClient.editConfig(message.clientConfig())));
        add(new TextButton(this, Component.translatable("ftblibrary.server_settings"), Icons.GLOBE,
                (widget, button) -> ConfigManagerClient.editConfig(message.serverConfig())));
        add(new TextButton(this, CommonComponents.GUI_BACK, Icons.BACK,
                (widget, button) -> closeGui()));
    }

    @Override
    public void alignWidgets() {
        int ySize = BTN_HEIGHT * 3 + 10;
        int xSize = 50 + widgets.stream().map(w -> getTheme().getStringWidth(w.getTitle())).max(Integer::compare).orElse(100);
        int yPos = (getWindow().getGuiScaledHeight() - ySize) / 2;
        for (Widget w : widgets) {
            w.setPosAndSize((getWindow().getGuiScaledWidth() - xSize) / 2, yPos, xSize, BTN_HEIGHT);
            yPos += BTN_HEIGHT + 5;
        }
    }

    @Override
    public boolean onInit() {
        return setFullscreen();
    }

    @Override
    public void drawBackground(GuiGraphicsExtractor graphics, Theme theme, int x, int y, int w, int h) {
    }

    private static class TextButton extends SimpleTextButton {
        public interface Callback {
            void onClicked(TextButton widget, MouseButton button);
        }

        private final Callback callback;

        public TextButton(Panel panel, Component txt, Icon<?> icon, Callback callback) {
            super(panel, txt, icon);
            this.callback = callback;
        }

        @Override
        public void onClicked(MouseButton button) {
            callback.onClicked(this, button);
        }

        @Override
        public boolean renderTitleInCenter() {
            return true;
        }
    }
}

package dev.ftb.mods.ftblibrary.client.config.gui;

import com.mojang.blaze3d.platform.InputConstants;
import dev.ftb.mods.ftblibrary.client.config.EditableConfigGroup;
import dev.ftb.mods.ftblibrary.client.config.editable.EditableConfigValue;
import dev.ftb.mods.ftblibrary.client.gui.input.Key;
import dev.ftb.mods.ftblibrary.client.gui.input.MouseButton;
import dev.ftb.mods.ftblibrary.client.gui.layout.WidgetLayout;
import dev.ftb.mods.ftblibrary.client.gui.screens.AbstractThreePanelScreen;
import dev.ftb.mods.ftblibrary.client.gui.theme.Theme;
import dev.ftb.mods.ftblibrary.client.gui.widget.*;
import dev.ftb.mods.ftblibrary.client.icon.IconHelper;
import dev.ftb.mods.ftblibrary.icon.Color4I;
import dev.ftb.mods.ftblibrary.icon.Icons;
import dev.ftb.mods.ftblibrary.util.TooltipList;
import net.minecraft.ChatFormatting;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.resources.language.I18n;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.network.chat.Style;
import net.minecraft.network.chat.TextColor;
import net.minecraft.util.Mth;
import org.apache.commons.lang3.mutable.MutableInt;
import org.jspecify.annotations.Nullable;
import org.lwjgl.glfw.GLFW;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Supplier;

import static dev.ftb.mods.ftblibrary.util.TextComponentUtils.hotkeyTooltip;

public class EditConfigScreen extends AbstractThreePanelScreen<EditConfigScreen.ConfigPanel> {
    private final EditableConfigGroup group;
    private final Component title;
    private final List<Widget> allConfigButtons; // both groups and entries
    private final Button buttonCollapseAll, buttonExpandAll;

    private int groupSize = 0;
    private boolean autoclose = false;
    private int widestKey = 0;
    private int widestValue = 0;
    private boolean changed = false;
    private boolean openPrevScreenOnClose = true;
    private final boolean readOnly;

    public EditConfigScreen(EditableConfigGroup configGroup) {
        this(configGroup, false);
    }

    public EditConfigScreen(EditableConfigGroup configGroup, boolean readOnly) {
        super();

        this.readOnly = readOnly;
        group = configGroup;
        MutableComponent baseTitle = configGroup.getName().copy().withStyle(ChatFormatting.BOLD);
        title = readOnly ? baseTitle.append(" (").append(Component.translatable("ftblibrary.read_only")).append(")") : baseTitle;
        allConfigButtons = new ArrayList<>();

        List<EditableConfigValue<?>> list = new ArrayList<>();
        collectAllConfigValues(group, list);

        if (!list.isEmpty()) {
            ConfigGroupButton group = null;

            for (var value : list) {
                if (group == null || group.group != value.getGroup()) {
                    allConfigButtons.add(new VerticalSpaceWidget(mainPanel, 4));
                    group = new ConfigGroupButton(mainPanel, value.getGroup());
                    allConfigButtons.add(group);
                    groupSize++;
                }

                ConfigEntryButton<?> btn = new ConfigEntryButton<>(mainPanel, group, value);
                allConfigButtons.add(btn);
            }

            if (groupSize == 1) {
                allConfigButtons.remove(group);
            }
        }

        buttonExpandAll = new SimpleButton(topPanel, List.of(Component.translatable("gui.expand_all"), hotkeyTooltip("="), hotkeyTooltip("+")), Icons.EXPAND,
                (_, _) -> toggleAll(false));
        buttonCollapseAll = new SimpleButton(topPanel, List.of(Component.translatable("gui.collapse_all"), hotkeyTooltip("-")), Icons.COLLAPSE,
                (_, _) -> toggleAll(true));
    }

    private void toggleAll(boolean collapsed) {
        for (var w : allConfigButtons) {
            if (w instanceof ConfigGroupButton cgb) {
                cgb.setCollapsed(collapsed);
            }
        }

        scrollBar.setValue(0);
        getGui().refreshWidgets();
    }

    private void collectAllConfigValues(EditableConfigGroup group, List<EditableConfigValue<?>> list) {
        list.addAll(group.getValues().stream().sorted().toList());

        for (var subgroup : group.getSubgroups()) {
            collectAllConfigValues(subgroup, list);
        }
    }

    @Override
    public boolean onInit() {
        widestKey = widestValue = 0;
        MutableInt widestGroup = new MutableInt(0);
        MutableInt cfgHeight = new MutableInt(0);

        allConfigButtons.forEach(w -> {
            if (w instanceof ConfigEntryButton<?> eb) {
                widestKey = Math.max(widestKey, getTheme().getFont().width(eb.keyText.get()));
                widestValue = Math.max(widestValue, getTheme().getFont().width(eb.getValueStr()));
            } else if (w instanceof ConfigGroupButton gb) {
                widestGroup.setValue(Math.max(widestGroup.intValue(), getTheme().getStringWidth(gb.title)));
            }
            cfgHeight.add(w.height + 2);
        });

        setHeight(Mth.clamp(cfgHeight.intValue() + getTopPanelHeight() + BOTTOM_PANEL_H, 100, (int) (getWindow().getGuiScaledHeight() * .9f)));
        setWidth(Mth.clamp(Math.max(16 + widestKey + widestValue, widestGroup.intValue()) + 50, 176, (int) (getWindow().getGuiScaledWidth() * .9f)));

        return true;
    }

    /**
     * Set auto-close behaviour when Accept or Cancel buttons are clicked
     * @param autoclose true to close the config screen, false if the config group's save-callback should handle it
     */
    public EditConfigScreen setAutoclose(boolean autoclose) {
        this.autoclose = autoclose;
        return this;
    }

    public EditConfigScreen setOpenPrevScreenOnClose(boolean openPrevScreenOnClose) {
        this.openPrevScreenOnClose = openPrevScreenOnClose;
        return this;
    }

    @Override
    protected int getTopPanelHeight() {
        return 20;
    }

    @Override
    protected Panel createTopPanel() {
        return new CustomTopPanel();
    }

    @Override
    protected ConfigPanel createMainPanel() {
        return new ConfigPanel();
    }

    @Override
    protected void doAccept() {
        if (!readOnly) group.save(true);
        if (autoclose) closeGui(openPrevScreenOnClose);
    }

    @Override
    protected void doCancel() {
        if (changed) {
            openYesNo(Component.translatable("ftblibrary.unsaved_changes"), Component.empty(), this::reallyCancel);
        } else {
            reallyCancel();
        }
    }

    private void reallyCancel() {
        group.save(false);
        if (autoclose) closeGui(openPrevScreenOnClose);
    }

    @Override
    public boolean onClosedByKey(Key key) {
        if (super.onClosedByKey(key)) {
            doCancel();
            return true;
        }

        return false;
    }

    @Override
    public boolean keyPressed(Key event) {
        if (super.keyPressed(event)) {
            return true;
        } else if (event.is(InputConstants.KEY_ADD) || event.is(InputConstants.KEY_EQUALS)) {
            buttonExpandAll.onClicked(MouseButton.LEFT);
        } else if (event.is(InputConstants.KEY_MINUS) || event.is(GLFW.GLFW_KEY_KP_SUBTRACT)) {
            buttonCollapseAll.onClicked(MouseButton.LEFT);
        }
        return false;
    }

    @Override
    public boolean shouldCloseOnEsc() {
        return false;
    }

    @Override
    public Component getTitle() {
        return title;
    }

    public static class ConfigGroupButton extends Button {
        private final EditableConfigGroup group;
        @Nullable private final MutableComponent info;
        private final MutableComponent title;
        private boolean collapsed = false;

        public ConfigGroupButton(Panel panel, EditableConfigGroup g) {
            super(panel);
            setHeight(14);
            group = g;

            if (group.getParent() != null) {
                List<EditableConfigGroup> groups = new ArrayList<>();
                while (g.getParent() != null) {
                    groups.add(g);
                    g = g.getParent();
                }
                title = groups.stream()
                        .map(grp -> Component.translatable(grp.getNameKey()).withStyle(ChatFormatting.YELLOW))
                        .reduce((g1, g2) -> g2.append(Component.literal(" → ").withStyle(ChatFormatting.GOLD)).append(g1))
                        .orElse(Component.empty());
            } else {
                title = Component.translatable("stat.generalButton").withStyle(ChatFormatting.YELLOW);
            }

            var infoKey = group.getPath() + ".info";
            info = I18n.exists(infoKey) ? Component.translatable(infoKey) : null;
            setCollapsed(collapsed);
        }

        public void setCollapsed(boolean collapsed) {
            this.collapsed = collapsed;
            setTitle(Component.literal(this.collapsed ? "▶ " : "▼ ").withStyle(this.collapsed ? ChatFormatting.RED : ChatFormatting.GREEN).append(title));
        }

        @Override
        public void draw(GuiGraphicsExtractor graphics, Theme theme, int x, int y, int w, int h) {
            theme.drawWidget(graphics, x, y, w, h, getWidgetType());
            theme.drawString(graphics, getTitle(), x + 3, y + 3);
            if (isMouseOver()) {
                IconHelper.renderIcon(Color4I.WHITE.withAlpha(33), graphics, x, y, w, h);
            }
        }

        @Override
        public void addMouseOverText(TooltipList list) {
            if (info != null) {
                list.add(info);
            }
        }

        @Override
        public void onClicked(MouseButton button) {
            setCollapsed(!collapsed);
            getGui().refreshWidgets();
        }
    }

    private class ConfigEntryButton<T> extends Button implements EditStringConfigOverlay.PosProvider {
        private final ConfigGroupButton groupButton;
        private final EditableConfigValue<T> configValue;
        private final Supplier<Component> keyText;

        public ConfigEntryButton(Panel panel, ConfigGroupButton groupButton, EditableConfigValue<T> configValue) {
            super(panel);
            setHeight(getTheme().getFontHeight() + 2);
            this.groupButton = groupButton;
            this.configValue = configValue;

            keyText = () -> this.configValue.getCanEdit() ?
                    Component.literal(this.configValue.getName()) :
                    Component.literal(this.configValue.getName()).withStyle(getTheme().hasDarkBackground() ? ChatFormatting.DARK_GRAY : ChatFormatting.GRAY);
        }

        @Override
        public void draw(GuiGraphicsExtractor graphics, Theme theme, int x, int y, int w, int h) {
            IconHelper.renderIcon(Icons.COLOR_BLANK.withColor(Color4I.GRAY), graphics, x, y + 1, 10, 10);
            IconHelper.renderIcon(Icons.INFO, graphics, x + 1, y + 2, 8, 8);

            theme.drawStringOnBackground(graphics, keyText.get(), x + 13, y + 2);

            Component valueText = configValue.getStringForGUI(configValue.getValue());

            int maxLen = width - (scrollBar.shouldDraw() ? scrollBar.width : 0) - widestKey;
            if (theme.getStringWidth(valueText) > maxLen) {
                valueText = Component.literal(theme.trimStringToWidth(valueText, maxLen).getString().trim() + "...");
            }

            var textCol = configValue.getColor(theme).mutable();
            textCol.setAlpha(configValue.getCanEdit() ? 255 : 128);

            if (isMouseOver()) {
                textCol.addBrightness(60);
                IconHelper.renderIcon(Color4I.WHITE.withAlpha(60), graphics, x, y, w, h);
            }

            IconHelper.renderIcon(Color4I.GRAY.withAlpha(33), graphics, x + widestKey + 18, y, 1, height);

            theme.drawString(graphics, valueText, x + widestKey + 23, y + 2, textCol, 0);
        }

        @Override
        public void onClicked(MouseButton button) {
            if (configValue.getCanEdit() && !readOnly && getMouseY() >= 20) {
                playClickSound();
                configValue.onClicked(this, button, accepted -> {
                    if (accepted) changed = true;
                    run();
                });
            }
        }

        @Override
        public void addMouseOverText(TooltipList list) {
            if (getMouseY() > 18) {
                int x = getMouseX() - getX();
                if (x < 16) {
                    list.add(keyText.get().copy().withStyle(ChatFormatting.UNDERLINE));
                    var tooltip = configValue.getTooltip();

                    if (!tooltip.isEmpty()) {
                        for (var s : tooltip.split("\n")) {
                            list.styledString(s, Style.EMPTY.withItalic(true).withColor(TextColor.fromLegacyFormat(ChatFormatting.GRAY)));
                        }
                    }

                    list.blankLine();
                    configValue.addInfo(list, getTheme());
                }
            }
        }

        Component getValueStr() {
            return configValue.getStringForGUI(configValue.getValue());
        }

        @Override
        public Offset getOverlayOffset() {
            return new Offset(widestKey + 12, -2);
        }
    }

    public class ConfigPanel extends Panel {
        public ConfigPanel() {
            super(EditConfigScreen.this);
        }

        @Override
        public void addWidgets() {
            for (var w : allConfigButtons) {
                if (!(w instanceof ConfigEntryButton<?> cgb) || !cgb.groupButton.collapsed) {
                    add(w);
                }
            }
        }

        @Override
        public void alignWidgets() {
            allConfigButtons.forEach(btn -> {
                btn.setX(1);
                btn.setWidth(width - 2);
            });

            align(WidgetLayout.VERTICAL);
        }
    }

    protected class CustomTopPanel extends TopPanel {
        private final TextField titleLabel = new TextField(this);

        @Override
        public void addWidgets() {
            titleLabel.setText(getGui().getTitle());
            titleLabel.addFlags(Theme.CENTERED_V);
            add(titleLabel);

            if (groupSize > 1) {
                add(buttonExpandAll);
                add(buttonCollapseAll);
            }
        }

        @Override
        public void alignWidgets() {
            titleLabel.setPosAndSize(4, 0, titleLabel.width, height);
            if (groupSize > 1) {
                buttonExpandAll.setPos(width - 18, 2);
                buttonCollapseAll.setPos(width - 38, 2);
            }
        }
    }
}

package dev.ftb.mods.ftblibrary.client.config.gui;

import dev.ftb.mods.ftblibrary.client.config.ConfigCallback;
import dev.ftb.mods.ftblibrary.client.config.editable.EditableStringifiedConfig;
import dev.ftb.mods.ftblibrary.client.gui.input.Key;
import dev.ftb.mods.ftblibrary.client.gui.input.MouseButton;
import dev.ftb.mods.ftblibrary.client.gui.theme.Theme;
import dev.ftb.mods.ftblibrary.client.gui.widget.*;
import dev.ftb.mods.ftblibrary.icon.Color4I;
import dev.ftb.mods.ftblibrary.icon.Icons;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.network.chat.Component;
import org.jspecify.annotations.Nullable;

import java.util.Objects;

public class EditStringConfigOverlay<T> extends ModalPanel {
    protected final EditField textBox;
    private final Button accept, cancel;
    private final EditableStringifiedConfig<T> config;
    private final ConfigCallback callback;
    private final TextField titleField;
    @Nullable
    private final Component title;
    private boolean addAcceptCancelButtons = true;
    private T currentValue;

    public EditStringConfigOverlay(Panel panel, EditableStringifiedConfig<T> config, ConfigCallback callback) {
        this(panel, config, callback, null);
    }

    public EditStringConfigOverlay(Panel panel, EditableStringifiedConfig<T> config, ConfigCallback callback, @Nullable Component title) {
        super(panel);
        this.config = config;
        this.callback = callback;
        this.currentValue = config.copy(config.getValue());
        this.title = title;

        width = Math.clamp(currentValue == null ? 0 : getGui().getTheme().getStringWidth(config.getStringFromValue(currentValue)) + 86,
                150, getWindow().getGuiScaledWidth() * 3 / 4);

        titleField = new TextField(this).addFlags(Theme.SHADOW).setText(Objects.requireNonNullElse(title, Component.empty()));
        titleField.setSize(0, 0);
        accept = new SimpleButton(this, Component.translatable("gui.accept"), Icons.ACCEPT, this::onAccepted);
        cancel = new SimpleButton(this, Component.translatable("gui.cancel"), Icons.CANCEL, this::onCancelled);
        textBox = new EditField();
    }

    public EditStringConfigOverlay<T> atPosition(int x, int y) {
        setPos(x, y);
        return this;
    }

    public EditStringConfigOverlay<T> atMousePosition() {
        int absX = Math.min(getMouseX(), getWindow().getGuiScaledWidth() - width);
        int absY = Math.min(getMouseY(), getWindow().getGuiScaledHeight() - height);
        return atPosition(absX - parent.getX(), absY - parent.getY() - (int) parent.getScrollY());
    }

    @Override
    public void addWidgets() {
        if (title != null) {
            add(titleField);
        }
        add(textBox);
        if(addAcceptCancelButtons) {
            add(accept);
            add(cancel);
        }
    }

    @Override
    public void alignWidgets() {
        if (title != null) {
            titleField.setPosAndSize(2, 2, width, getGui().getTheme().getFontHeight() + 4);
        }
        textBox.setPosAndSize(2, titleField.getHeight() + 1, width - 36, 14);
        if(addAcceptCancelButtons) {
            accept.setPos(textBox.width + 2, textBox.getPosY());
            cancel.setPos(accept.getPosX() + accept.width + 2, textBox.getPosY());
        }


        height = title == null ? 16 : 30;
    }

    @Override
    public boolean keyPressed(Key key) {
        if (key.esc()) {
            onCancelled(cancel, MouseButton.LEFT);
            return true;
        }
        return super.keyPressed(key);
    }

    @Override
    public void drawBackground(GuiGraphicsExtractor graphics, Theme theme, int x, int y, int w, int h) {
        theme.drawContextMenuBackground(graphics, x - 1, y - 1, w + 2, h + 2);
    }

    protected void onAccepted(Button btn, MouseButton mb) {
        if (textBox.isTextValid()) {
            config.updateValue(currentValue);
            callback.save(true);
            getGui().popModalPanel();
        }
    }

    protected void onCancelled(Button btn, MouseButton mb) {
        callback.save(false);
        getGui().popModalPanel();
    }

    /**
     * @param addAcceptCancelButtons if true, accept and cancel buttons will be added to the overlay
     */
    public void setAddAcceptCancelButtons(boolean addAcceptCancelButtons) {
        this.addAcceptCancelButtons = addAcceptCancelButtons;
    }

    /**
     * Provides positioning information for when an edit panel needs to be overlaid on the widget
     */
    public interface PosProvider {
        Offset getOverlayOffset();

        record Offset(int x, int y) {
            public static final Offset NONE = new Offset(0, 0);
        }
    }

    protected class EditField extends TextBox {
        public EditField() {
            super(EditStringConfigOverlay.this);

            setText(config.getStringFromValue(EditStringConfigOverlay.this.currentValue));
            textColor = Color4I.WHITE; //config.getColor(currentValue);
            setCursorPos(0);
            setSelectionPos(getText().length());
            setFocused(true);
        }

        @Override
        public boolean allowInput() {
            return config.getCanEdit();
        }

        @Override
        public boolean isValid(String txt) {
            return config.parse(null, txt);
        }

        @Override
        public void onTextChanged() {
            config.parse(t -> currentValue = t, getText());

            accept.setIcon(isTextValid() ? Icons.ACCEPT : Icons.ACCEPT.withTint(Color4I.DARK_GRAY.withAlpha(160)));
        }

        @Override
        public void onEnterPressed() {
            if (config.getCanEdit()) {
                accept.onClicked(MouseButton.LEFT);
            }
        }

        @Override
        public boolean mouseScrolled(double mouseX, double mouseY, double scrollX, double scrollY) {
            var directionlessDelta = scrollX != 0 ? scrollX : scrollY;
            return config.scrollValue(currentValue, directionlessDelta > 0).map(v -> {
                textBox.setText(config.getStringFromValue(v));
                textBox.setSelectionPos(textBox.getCursorPos());
                return true;
            }).orElse(super.mouseScrolled(mouseX, mouseY, scrollX, scrollY));
        }
    }
}

package dev.ftb.mods.ftblibrary.client.config.editable;

import dev.ftb.mods.ftblibrary.client.config.ConfigCallback;
import dev.ftb.mods.ftblibrary.client.config.EditableConfigGroup;
import dev.ftb.mods.ftblibrary.client.gui.input.MouseButton;
import dev.ftb.mods.ftblibrary.client.gui.theme.Theme;
import dev.ftb.mods.ftblibrary.client.gui.widget.Widget;
import dev.ftb.mods.ftblibrary.config.value.BaseValue;
import dev.ftb.mods.ftblibrary.icon.Color4I;
import dev.ftb.mods.ftblibrary.icon.Icon;
import dev.ftb.mods.ftblibrary.icon.Icons;
import dev.ftb.mods.ftblibrary.util.TooltipList;
import net.minecraft.ChatFormatting;
import net.minecraft.client.resources.language.I18n;
import net.minecraft.network.chat.Component;
import org.jspecify.annotations.Nullable;

import java.util.Objects;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;

/**
 * Base class for all editable configs. This is the "glue" between config objects as loaded from disk (see
 * {@link BaseValue}) and the GUI config editor.
 *
 * @param <T> the type of object being edited
 */
public abstract class EditableConfigValue<T> implements Comparable<EditableConfigValue<T>> {
    // these 5 fields are always init'd in the init() method, which is called from EditableConfigGroup#add
    @SuppressWarnings("NotNullFieldNotInitialized")
    public String id;
    @SuppressWarnings("NotNullFieldNotInitialized")
    protected T value;
    @SuppressWarnings("NotNullFieldNotInitialized")
    protected T defaultValue;
    @SuppressWarnings("NotNullFieldNotInitialized")
    private EditableConfigGroup group;
    @SuppressWarnings("NotNullFieldNotInitialized")
    private Consumer<T> setter;

    private int order = 0;
    private String nameKey = "";
    private Icon<?> icon = Icons.SETTINGS;
    private BooleanSupplier canEdit = () -> true;

    protected static Component info(String key) {
        return Component.literal(key + ":").withStyle(ChatFormatting.AQUA);
    }

    public static Component info(String key, Object value) {
        var title = value instanceof Component c ? c : Component.literal(String.valueOf(value));
        return Component.empty().append((Component.literal(key + ": ").withStyle(ChatFormatting.AQUA))).append(title);
    }

    /**
     * Initialise this config value; called when it's added to a config group with
     * {@link EditableConfigGroup#add(String, EditableConfigValue, Object, Consumer, Object)}
     *
     * @param group the group being added to
     * @param id a unique id for this value
     * @param value the initial value from the underlying config
     * @param setter a consumer to be called to apply changes back to the underlying config
     * @param defaultValue the default value
     * @return the initialised config value
     */
    public EditableConfigValue<T> init(EditableConfigGroup group, String id, T value, Consumer<T> setter, T defaultValue) {
        this.group = group;
        this.id = id;
        this.value = copy(value);
        this.setter = setter;
        this.defaultValue = defaultValue;
        return this;
    }

    /**
     * {@return the config group to which this editable belongs}
     */
    public EditableConfigGroup getGroup() {
        return group;
    }

    /**
     * {@return the current value for this editable}
     */
    public T getValue() {
        return value;
    }

    /**
     * Unconditionally set a new value. See also {@link #updateValue(Object)}
     * @param newValue the new value
     */
    public void setValue(T newValue) {
        this.value = newValue;
    }

    /**
     * Update the current value of this editable. This should be called from GUI code when a change shoud be applied.
     *
     * @param newValue the new value
     * @return true if the value was actually changed, false if the newValue is the same as value
     */
    public final boolean updateValue(T newValue) {
        if (!isEqual(value, newValue)) {
            value = newValue;
            return true;
        }

        return false;
    }

    /**
     * {@return the default value for this editable}
     */
    public T getDefaultValue() {
        return defaultValue;
    }

    /**
     * Set the default value for this editable. This is required if the value is some kind of container object, e.g.
     * a list or a map.
     * @param defaultValue the new default value
     */
    public void setDefaultValue(T defaultValue) {
        this.defaultValue = defaultValue;
    }

    /**
     * Compare two values for equality.
     *
     * @param v1 the first value
     * @param v2 the second value
     * @return true if the values are equal
     */
    public boolean isEqual(@Nullable T v1, @Nullable T v2) {
        return Objects.equals(v1, v2);
    }

    /**
     * Make a deep copy of this editable. Override this for mutable objects (e.g. lists, itemstacks) to correctly
     * return a new object. For immutable objects, returning the passed object is fine.
     *
     * @param value the value to copy
     * @return the new value
     */
    public T copy(T value) {
        return value;
    }

    /**
     * Get the color to represent the current value of this editable, for display purposes in the editor GUI.
     *
     * @param theme the GUI theme currently being used
     * @return the display color
     */
    public final Color4I getColor(Theme theme) {
        return getColor(value, theme);
    }

    /**
     * Get the color to represent some specific value of this editable, for display purposes in the editor GUI.
     *
     * @param value the object
     * @param theme the GUI theme currently being used
     * @return the display color
     */
    public Color4I getColor(T value, Theme theme) {
        return theme.hasDarkBackground() ? Color4I.GRAY : Color4I.DARK_GRAY;
    }

    /**
     * Add some descriptive text for this editable, for tooltip purposes in the editor GUI.
     *
     * @param list  the tooltip list to append to
     * @param theme the GUI theme currently being used
     */
    public void addInfo(TooltipList list, Theme theme) {
        list.add(info("Default", getStringForGUI(defaultValue)));
    }

    /**
     * Called when the widget displaying this config entry is clicked; implementations must provide the user with some
     * means of editing the value, which accepts the {@code callback} object that is passed.
     *
     * @param clickedWidget the widget that was clicked to trigger this method;
     *                         may be useful to help position the edit controls you display
     * @param button the mouse button that triggered this
     * @param callback called when the editing GUI is either accepted or cancelled
     */
    public abstract void onClicked(Widget clickedWidget, MouseButton button, ConfigCallback callback);

    public final Component getStringForGUI() {
        return Component.literal(String.valueOf(value));
    }

    public Component getStringForGUI(T value) {
        return Component.literal(String.valueOf(value));
    }

    public String getPath() {
        var path = group.getPath();
        return path.isEmpty() ? id : (path + '.' + id);
    }

    public String getNameKey() {
        return nameKey.isEmpty() ? getPath() : nameKey;
    }

    public EditableConfigValue<T> setNameKey(String key) {
        nameKey = key;
        return this;
    }

    public String getName() {
        return I18n.get(getNameKey());
    }

    public String getTooltip() {
        var k = getNameKey() + ".tooltip";
        return I18n.exists(k) ? I18n.get(k) : "";
    }

    public EditableConfigValue<T> setOrder(int o) {
        order = o;
        return this;
    }

    public boolean getCanEdit() {
        return canEdit.getAsBoolean();
    }

    public EditableConfigValue<T> setCanEdit(boolean e) {
        canEdit = () -> e;
        return this;
    }

    public EditableConfigValue<T> setCanEdit(BooleanSupplier e) {
        canEdit = e;
        return this;
    }

    public Icon<?> getIcon() {
        return getIcon(getValue());
    }

    public EditableConfigValue<T> setIcon(Icon<?> icon) {
        this.icon = icon;
        return this;
    }

    public Icon<?> getIcon(T value) {
        return icon;
    }

    @Override
    public int compareTo(EditableConfigValue<T> o) {
        // sort by group, then ordering, then display name
        var cg = group.compareTo(o.group);
        if (cg != 0) return cg;
        int co = Integer.compare(order, o.order);
        return co != 0 ? co : getName().compareTo(o.getName());
    }

    /**
     * Called when a config group is saved via the config editor screen to actually apply the changes.
     */
    public void applyValue() {
        setter.accept(value);
    }
}

package dev.ftb.mods.ftblibrary.config.manager;

import dev.ftb.mods.ftblibrary.client.config.gui.EditConfigScreen;
import dev.ftb.mods.ftblibrary.config.ConfigUtil;
import net.minecraft.client.Minecraft;

public class ConfigManagerClient {
    public static void onClientStarted(Minecraft minecraft) {
        ConfigManager mgr = ConfigManager.getInstance();

        mgr.pendingClient.forEach((key, config) -> {
            mgr.findAndLoad(key, config, ConfigUtil.LOCAL_DIR::resolve);
        });

        // all synced server configs are also registered on the client (but not saved there!)
        mgr.pendingServer.forEach((key, config) -> {
            if (config.synced()) {
                mgr.startTracking(key, config.clientMirrorOfServerConfig());
            }
        });
    }

    public static void editConfig(String configName) {
        editConfig(configName, false);
    }

    public static void editConfig(String configName, boolean isReadOnly) {
        ConfigManager.getInstance().createConfigGroup(configName)
                .ifPresent(group -> new EditConfigScreen(group, isReadOnly).setAutoclose(true).openGui());
    }
}

package dev.ftb.mods.ftblibrary.client.gui.screens;

import com.mojang.blaze3d.platform.InputConstants;
import com.mojang.datafixers.util.Pair;
import dev.ftb.mods.ftblibrary.client.gui.input.Key;
import dev.ftb.mods.ftblibrary.client.gui.theme.Theme;
import dev.ftb.mods.ftblibrary.client.gui.theme.ThemeManager;
import dev.ftb.mods.ftblibrary.client.gui.widget.*;
import dev.ftb.mods.ftblibrary.client.icon.IconHelper;
import dev.ftb.mods.ftblibrary.icon.Color4I;
import dev.ftb.mods.ftblibrary.icon.Icons;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.network.chat.Component;

import static dev.ftb.mods.ftblibrary.util.TextComponentUtils.hotkeyTooltip;

public abstract class AbstractThreePanelScreen<T extends Panel> extends BaseScreen {
    public static final Pair<Integer, Integer> NO_INSET = Pair.of(0, 0);
    protected static final int BOTTOM_PANEL_H = 25;
    private static final int SCROLLBAR_WIDTH = 12;
    protected final Panel topPanel;
    protected final T mainPanel;
    protected final Panel bottomPanel;
    protected final PanelScrollBar scrollBar;
    private boolean showBottomPanel = true;
    private boolean showCloseButton = false;
    private boolean showScrollBar = true;

    protected AbstractThreePanelScreen() {
        super();

        topPanel = createTopPanel();
        mainPanel = createMainPanel();
        bottomPanel = createBottomPanel();
        scrollBar = new PanelScrollBar(this, ScrollBar.Plane.VERTICAL, mainPanel);
    }

    @Override
    public void addWidgets() {
        add(topPanel);
        add(mainPanel);
        if (showScrollBar) {
            add(scrollBar);
        }
        if (showBottomPanel) {
            add(bottomPanel);
        }
    }

    @Override
    public void alignWidgets() {
        int topPanelHeight = getTopPanelHeight();

        topPanel.setPosAndSize(0, 0, width, topPanelHeight);
        topPanel.alignWidgets();

        var inset = mainPanelInset();
        int bottomPanelHeight = showBottomPanel ? getBottomPanelHeight() + inset.getSecond() : 0;

        mainPanel.setPosAndSize(inset.getFirst(), topPanelHeight + inset.getSecond(),
                width - inset.getFirst() * 2, height - topPanelHeight - inset.getSecond() * 2 - bottomPanelHeight);
        mainPanel.alignWidgets();

        if (showBottomPanel) {
            bottomPanel.setPosAndSize(0, height - getBottomPanelHeight(), width, getBottomPanelHeight());
            bottomPanel.alignWidgets();
        }

        if (showScrollBar) {
            scrollBar.setPosAndSize(mainPanel.getPosX() + mainPanel.getWidth() - getScrollbarWidth(), mainPanel.getPosY(), getScrollbarWidth(), mainPanel.getHeight());
        }
    }

    @Override
    public Theme getTheme() {
        // TODO ultimately move this up to BaseScreen once theming is fully functional
        return ThemeManager.INSTANCE.getActiveTheme();
    }

    @Override
    public void tick() {
        super.tick();

        int prevWidth = mainPanel.width;
        int newWidth = (showScrollBar && scrollBar.shouldDraw() ? getGui().width - getScrollbarWidth() - 2 : getGui().width) - mainPanelInset().getFirst() * 2;
        if (prevWidth != newWidth) {
            mainPanel.setWidth(newWidth);
            mainPanel.alignWidgets();
        }
    }

    @Override
    public boolean keyPressed(Key event) {
        if (super.keyPressed(event)) {
            return true;
        } else if ((event.is(InputConstants.KEY_RETURN) || event.is(InputConstants.KEY_NUMPADENTER)) && event.modifiers().shift()) {
            this.doAccept();
            return true;
        } else {
            return false;
        }
    }

    protected abstract void doCancel();

    protected abstract void doAccept();

    protected abstract int getTopPanelHeight();

    protected abstract T createMainPanel();

    protected Pair<Integer, Integer> mainPanelInset() {
        return NO_INSET;
    }

    protected int getBottomPanelHeight() {
        return BOTTOM_PANEL_H;
    }

    protected int getScrollbarWidth() {
        return SCROLLBAR_WIDTH;
    }

    protected Panel createTopPanel() {
        return new TopPanel();
    }

    protected Panel createBottomPanel() {
        return new BottomPanel();
    }

    public void showBottomPanel(boolean show) {
        showBottomPanel = show;
    }

    public void showCloseButton(boolean show) {
        showCloseButton = show;
    }

    public boolean shouldShowCloseButton() {
        return showCloseButton;
    }

    public void showScrollBar(boolean show) {
        showScrollBar = show;
    }

    protected class TopPanel extends Panel {
        private final SimpleButton closeButton;

        public TopPanel() {
            super(AbstractThreePanelScreen.this);

            closeButton = new SimpleButton(this, Component.translatable("gui.close"), Icons.CANCEL, (btn, mb) -> doCancel());
        }

        @Override
        public void addWidgets() {
            if (showCloseButton) {
                add(closeButton);
            }
        }

        @Override
        public void alignWidgets() {
            if (showCloseButton) {
                closeButton.setPosAndSize(width - 16, (height - 14) / 2, 14, 14);
            }
        }

        @Override
        public void drawBackground(GuiGraphicsExtractor graphics, Theme theme, int x, int y, int w, int h) {
            theme.drawPanelBackground(graphics, x, y, w, h);
            IconHelper.renderIcon(Color4I.BLACK.withAlpha(80), graphics, x, y + h - 1, w, 1);
        }
    }

    private class BottomPanel extends Panel {
        private final Button buttonAccept, buttonCancel;

        public BottomPanel() {
            super(AbstractThreePanelScreen.this);

            buttonAccept = SimpleTextButton.accept(this, mb -> doAccept(), hotkeyTooltip("⇧ + Enter"));
            buttonCancel = SimpleTextButton.cancel(this, mb -> doCancel(), hotkeyTooltip("ESC"));
        }

        @Override
        public void addWidgets() {
            add(buttonAccept);
            add(buttonCancel);
        }

        @Override
        public void alignWidgets() {
            buttonCancel.setPos(width - buttonCancel.width - 5, 2);
            buttonAccept.setPos(buttonCancel.posX - buttonAccept.width - 5, 2);
        }

        @Override
        public void drawBackground(GuiGraphicsExtractor graphics, Theme theme, int x, int y, int w, int h) {
            theme.drawPanelBackground(graphics, x, y, w, h);
            IconHelper.renderIcon(Color4I.GRAY.withAlpha(64), graphics, x, y, w, 1);
        }
    }
}

package dev.ftb.mods.ftblibrary.client.gui.widget;

import com.mojang.blaze3d.platform.InputConstants;
