import dev.ftb.mods.ftblibrary.client.gui.input.MouseButton;
import dev.ftb.mods.ftblibrary.client.gui.screens.LoadingScreen;
import dev.ftb.mods.ftblibrary.client.gui.theme.Theme;
import dev.ftb.mods.ftblibrary.client.gui.theme.ThemeManager;
import dev.ftb.mods.ftblibrary.client.icon.IconHelper;
import dev.ftb.mods.ftblibrary.client.util.ClientUtils;
import dev.ftb.mods.ftblibrary.icon.Color4I;
import dev.ftb.mods.ftblibrary.util.TooltipList;
import it.unimi.dsi.fastutil.booleans.BooleanConsumer;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.gui.screens.ChatScreen;
import net.minecraft.client.gui.screens.ConfirmScreen;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.client.input.CharacterEvent;
import net.minecraft.network.chat.Component;
import org.apache.commons.lang3.Validate;
import org.jspecify.annotations.NonNull;
import org.jspecify.annotations.Nullable;
import org.lwjgl.glfw.GLFW;

import java.util.*;

public abstract class BaseScreen extends Panel {
    @Nullable private Screen prevScreen;
    private final Deque<ModalPanel> modalPanels;
    private int mouseX, mouseY;
    private float partialTicks;
    private boolean refreshWidgets;
    private long lastClickTime = 0L;
    @Nullable private Widget focusedWidget = null;
    private boolean renderBlur = true;

    public BaseScreen(@Nullable Screen previousScreen) {
        super(null);

        setSize(176, 166);
        setOnlyRenderWidgetsInside(false);
        setOnlyInteractWithWidgetsInside(false);
        prevScreen = previousScreen;
        modalPanels = new ArrayDeque<>();
    }

    public BaseScreen() {
        this(Minecraft.getInstance().screen);
    }

    /**
     * Sets the previous screen that will be opened when this screen is closed.
     *
     * @param prevScreen the previous screen, or null to just close the GUI
     */
    public void setPreviousScreen(@Nullable Screen prevScreen) {
        this.prevScreen = prevScreen;
    }

    @Override
    public final BaseScreen getGui() {
        return this;
    }

    @Override
    public void alignWidgets() {
    }

    public final void initGui() {
        if (onInit()) {
            super.refreshWidgets();
            alignWidgets();
            onPostInit();
        }
    }

    public Theme getTheme() {
        return ThemeManager.INSTANCE.getActiveTheme();
    }

    @Override
    public int getX() {
        return (getWindow().getGuiScaledWidth() - width) / 2;
    }

    @Override
    public int getY() {
        return (getWindow().getGuiScaledHeight() - height) / 2;
    }

    @Override
    public double getScrollX() {
        return 0;
    }

    @Override
    public void setScrollX(double scroll) {
    }

    @Override
    public double getScrollY() {
        return 0;
    }

    @Override
    public void setScrollY(double scroll) {
    }

    public boolean onInit() {
        return true;
    }

    /**
     * @return if the GUI should render a blur effect behind it
     */
    public boolean shouldRenderBlur() {
        return renderBlur;
    }

    /**
     * @param renderBlur sets if the GUI should render a blur effect behind it
     */
    public void setRenderBlur(boolean renderBlur) {
        this.renderBlur = renderBlur;
    }

    /**
     * Should the GUI automatically close when Escape (or the inventory key - E by default) is pressed? Override this
     * to return false if you need to implement custom close behaviour, e.g. a confirmation screen for unsaved changes.
     *
     * @return autoclose behaviour, true by default
     */
    public boolean shouldCloseOnEsc() {
        return true;
    }

    protected boolean setFullscreen() {
        return setSizeProportional(1f, 1f);
    }

    protected boolean setSizeProportional(float w, float h) {
        Validate.isTrue(w > 0f && w <= 1f && h > 0f && h <= 1f, "width and height must be > 0 and <= 1");

        setWidth((int) (getWindow().getGuiScaledWidth() * w));
        setHeight((int) (getWindow().getGuiScaledHeight() * h));
        return true;
    }

    public void onPostInit() {
    }

    /**
     * Push a modal panel onto the stack. It will render above any existing modal panels and take key/mouse input first.
     *
     * @param modalPanel the panel to push
     */
    public void pushModalPanel(ModalPanel modalPanel) {
        modalPanels.addFirst(modalPanel);
        modalPanel.refreshWidgets();

        // since the panel size will have changed, make sure it's still on-screen
        modalPanel.setX(Math.min(modalPanel.getX(), getWidth() - modalPanel.getWidth() - 10));
        modalPanel.setY(Math.min(modalPanel.getY(), getHeight() - modalPanel.getHeight() - 10));
    }

    /**
     * Close the top modal panel, by removing it from the stack.
     *
     * @return the panel that was just popped/closed, or null if no modal panels were present
     */
    @Nullable
    public ModalPanel popModalPanel() {
        if (modalPanels.isEmpty()) {
            return null;
        }
        ModalPanel panel = modalPanels.removeFirst();
        panel.onClosed();
        focusedWidget = null;  // in case an editfield in the panel had focus
        return panel;
    }

    /**
     * Close the given panel, and all panels above it, from the stack
     *
     * @param panel the panel to pop/close
     */
    public void closeModalPanel(ModalPanel panel) {
        if (modalPanels.contains(panel)) {
            while (!modalPanels.isEmpty()) {
                if (popModalPanel() == panel) {
                    break;
                }
            }
        }
    }

    public boolean anyModalPanelOpen() {
        return !modalPanels.isEmpty();
    }

    @Override
    public void tick() {
        super.tick();

        modalPanels.forEach(Panel::tick);
    }

    @Nullable
    public Screen getPrevScreen() {
        if (prevScreen instanceof ScreenWrapper sw && sw.getGui() instanceof LoadingScreen) {
            return sw.getGui().getPrevScreen();
        } else if (prevScreen instanceof ChatScreen) {
            return null;
        }

        return prevScreen;
    }

    /**
     * Close the GUI and optionally open the previous screen.
     *
     * @param openPrevScreen if true, will open the previous screen if the {@link #usePreviousScreenOnBack()} method returns true
     */
    @Override
    public final void closeGui(boolean openPrevScreen) {
        var mc = getMinecraft();

        var mx = mc.mouseHandler.xpos();
        var my = mc.mouseHandler.ypos();

        if (mc.player != null) {
            mc.player.closeContainer();
        }

        if (usePreviousScreenOnBack()) {
            if (openPrevScreen && getPrevScreen() != null) {
                mc.setScreen(getPrevScreen());
                GLFW.glfwSetCursorPos(getWindow().handle(), mx, my);
            }
        }

        modalPanels.clear();

        onClosed();
    }

    public boolean onClosedByKey(Key event) {
        return event.escOrInventory();
    }

    public void onBack() {
        closeGui(true);
    }

    public boolean doesGuiPauseGame() {
        return false;
    }

    @Override
    public final void refreshWidgets() {
        refreshWidgets = true;
    }

    public final void updateGui(int mx, int my, float pt) {
        mouseX = mx;
        mouseY = my;
        partialTicks = pt;

        if (refreshWidgets) {
            super.refreshWidgets();
            modalPanels.forEach(Panel::refreshWidgets);
            refreshWidgets = false;
        }

        posX = getX();
        posY = getY();

        updateMouseOver(mouseX, mouseY);
    }

    @Override
    public void updateMouseOver(int mouseX, int mouseY) {
        isMouseOver = checkMouseOver(mouseX, mouseY);

        doWithScrollOffset(() -> {
            modalPanels.forEach(p -> p.updateMouseOver(mouseX, mouseY));
            widgets.forEach(w -> w.updateMouseOver(mouseX, mouseY));

        });
    }

    @Override
    public final void draw(GuiGraphicsExtractor graphics, Theme theme, int x, int y, int w, int h) {
        super.draw(graphics, theme, x, y, w, h);

        if (!modalPanels.isEmpty()) {
            // allow modal panels to draw outside scissor area if needed
            boolean r = getOnlyRenderWidgetsInside();
            boolean i = getOnlyInteractWithWidgetsInside();
            setOnlyRenderWidgetsInside(false);
            setOnlyInteractWithWidgetsInside(false);

            graphics.pose().pushMatrix();
            Iterator<ModalPanel> iter = modalPanels.descendingIterator(); // stack is drawn from bottom to top
            while (iter.hasNext()) {
                ModalPanel p = iter.next();
                if (!iter.hasNext()) {
                    // dim the rest of the gui so the top modal panel is effectively highlighted
                    IconHelper.renderIcon(Color4I.rgba(0xA0202020), graphics, 0, 0, getWindow().getGuiScaledWidth(), getWindow().getGuiScaledHeight());
                }
                p.draw(graphics, theme, p.getX(), p.getY(), p.getWidth(), p.getHeight());
            }
            graphics.pose().popMatrix();

            setOnlyRenderWidgetsInside(r);
            setOnlyInteractWithWidgetsInside(i);
        }
    }

    public Optional<ModalPanel> getContextMenu() {
        return modalPanels.stream().filter(p -> p instanceof PopupMenu).findFirst();
    }

    public void openPopupMenu(@Nullable PopupMenu popupMenu) {
        if (popupMenu == null) {
            modalPanels.removeIf(p -> p instanceof PopupMenu);
            return;
        }

        pushModalPanel(popupMenu.getModalPanel());

        // default positioning where the mouse was clicked. caller is free to reposition if needed
        var x = getX();
        var y = getY();
        int px = Math.min((getMouseX() - x), getWindow().getGuiScaledWidth() - popupMenu.getModalPanel().width - x) - 3;
        int py = Math.min((getMouseY() - y), getWindow().getGuiScaledHeight() - popupMenu.getModalPanel().height - y) - 3;
        popupMenu.getModalPanel().setPos(px, py);
    }

    public void openContextMenu(@Nullable ContextMenu newContextMenu) {
        openPopupMenu(newContextMenu);
    }

    public ContextMenu openContextMenu(@NonNull List<ContextMenuItem> menuItems) {
        var contextMenu = new ContextMenu(this, menuItems);
        openContextMenu(contextMenu);
        return contextMenu;
    }

    public void openDropdownMenu(@Nullable DropDownMenu dropDownMenu) {
        openPopupMenu(dropDownMenu);
    }

    public DropDownMenu openDropdownMenu(@NonNull List<ContextMenuItem> menuItems) {
        var contextMenu = new DropDownMenu(this, menuItems);
        openDropdownMenu(contextMenu);
        return contextMenu;
    }

    @Override
    public void closeContextMenu() {
        openContextMenu((ContextMenu) null);
    }

    @Override
    public void onClosed() {
        super.onClosed();
        closeContextMenu();
        CursorType.set(null);
    }

    @Override
    public void drawBackground(GuiGraphicsExtractor graphics, Theme theme, int x, int y, int w, int h) {
        theme.drawGui(graphics, x, y, w, h, WidgetType.NORMAL);
    }


    public boolean drawDefaultBackground(GuiGraphicsExtractor graphics) {
        return true;
    }

    public void drawForeground(GuiGraphicsExtractor graphics, Theme theme, int x, int y, int w, int h) {
    }

    private Panel getDoubleClickTarget() {
        return modalPanels.isEmpty() ? this : modalPanels.peekFirst();
    }

    public int getMaxZLevel() {
        return modalPanels.stream().map(ModalPanel::getExtraZlevel).max(Integer::compare).orElse(0);
    }

    @Override
    public boolean mousePressed(MouseButton button) {
        if (button == MouseButton.BACK) {
            closeGui(true);
            return true;
        }

        var now = System.currentTimeMillis();
        if (lastClickTime != 0L && (now - lastClickTime) <= 300L && getDoubleClickTarget().mouseDoubleClicked(button)) {
            lastClickTime = 0L;
            return true;
        }
        lastClickTime = now;

        if (modalPanels.isEmpty()) {
            return super.mousePressed(button);
        } else if (modalPanels.peekFirst().isMouseOver()) {
            return modalPanels.peekFirst().mousePressed(button);
        } else {
            // clicking outside any panel dismisses the top one
            popModalPanel();
            return false;
        }
    }

    @Override
    public boolean keyPressed(Key event) {
        if (focusedWidget != null && focusedWidget.keyPressed(event)) {
            return true;
        } else if (!modalPanels.isEmpty()) {
            if (event.esc()) {
                popModalPanel();
                return true;
            }
            //noinspection DataFlowIssue
            return modalPanels.peekFirst().keyPressed(event);  // we already checked it's not empty
        } else if (super.keyPressed(event)) {
            return true;
        } else if (InputConstants.isKeyDown(getWindow(), GLFW.GLFW_KEY_F3) && event.is(GLFW.GLFW_KEY_B)) {
            Theme.renderDebugBoxes = !Theme.renderDebugBoxes;
            return true;
        }

        return false;
    }

    @Override
    public boolean keyReleased(Key key) {
        return modalPanels.isEmpty() ? super.keyReleased(key) : modalPanels.peekFirst().keyReleased(key);
    }

    @Override
    public boolean mouseDoubleClicked(MouseButton button) {
        return modalPanels.isEmpty() ? super.mouseDoubleClicked(button) : modalPanels.peekFirst().mouseDoubleClicked(button);
    }

    @Override
    public void mouseReleased(MouseButton button) {
        if (modalPanels.isEmpty()) {
            super.mouseReleased(button);
        } else {
            modalPanels.peekFirst().mouseReleased(button);
        }
    }

    @Override
    public boolean mouseScrolled(double mouseX, double mouseY, double scrollX, double scrollY) {
        if (focusedWidget != null && focusedWidget.mouseScrolled(mouseX, mouseY, scrollX, scrollY)) {
            return true;
        }
        return modalPanels.isEmpty() ? super.mouseScrolled(mouseX, mouseY, scrollX, scrollY) : modalPanels.peekFirst().mouseScrolled(mouseX, mouseY, scrollX, scrollY);
    }

    @Override
    public boolean mouseDragged(int button, double dragX, double dragY) {
        return modalPanels.isEmpty() ? super.mouseDragged(button, dragX, dragY) : modalPanels.peekFirst().mouseDragged(button, dragX, dragY);
    }

    @Override
    public boolean charTyped(CharacterEvent event) {
        if (focusedWidget != null && focusedWidget.charTyped(event)) {
            return true;
        }
        return modalPanels.isEmpty() ? super.charTyped(event) : modalPanels.peekFirst().charTyped(event);
    }

    @Override
    public boolean shouldAddMouseOverText() {
        return getContextMenu().isEmpty();
    }

    @Override
    public void addMouseOverText(TooltipList list) {
        if (!modalPanels.isEmpty()) {
            modalPanels.peekFirst().addMouseOverText(list);
        } else {
            super.addMouseOverText(list);
        }
    }

    @Override
    public final void openGui() {
        openContextMenu((ContextMenu) null);
        getMinecraft().setScreen(new ScreenWrapper(this));
    }

    @Override
    public Window getWindow() {
        return getMinecraft().getWindow();
    }

    @Override
    public final int getMouseX() {
        return mouseX;
    }

    @Override
    public final int getMouseY() {
        return mouseY;
    }

    @Override
    public final float getPartialTicks() {
        return partialTicks;
    }

    public boolean isMouseOver(int x, int y, int w, int h) {
        return getMouseX() >= x && getMouseY() >= y && getMouseX() < x + w && getMouseY() < y + h;
    }

    public boolean isMouseOver(Widget widget) {
        if (widget == this) {
            return isMouseOver(getX(), getY(), width, height);
        } else if (isMouseOver(widget.getX(), widget.getY(), widget.width, widget.height)) {
            var offset = widget.getParent().isOffset();
            widget.getParent().setOffset(false);
            var b = isMouseOver(widget.getParent());
            widget.getParent().setOffset(offset);
            return b;
        }

        return false;
    }

    @Override
    public boolean handleClick(String scheme, String path) {
        return ClientUtils.handleClick(scheme, path);
    }

    public void openYesNoFull(Component title, Component desc, BooleanConsumer callback) {
        getMinecraft().setScreen(new ConfirmScreen(result -> {
            openGui();
            callback.accept(result);
            refreshWidgets();
        }, title, desc));
    }

    public final void openYesNo(Component title, Component desc, Runnable callback) {
        openYesNoFull(title, desc, result -> {
            if (result) {
                callback.run();
            }
        });
    }

    public void setFocusedWidget(Widget widget) {
        Validate.isTrue(widget instanceof IFocusableWidget);
        if (focusedWidget instanceof IFocusableWidget f && focusedWidget != widget) {
            f.setFocused(false);
        }
        focusedWidget = widget;
    }

    /**
     * Override this method to completely disable going back to the previous screen on various
     * back actions (e.g. pressing esc, calling back, etc).
     *
     * @return true to use the previous screen on back actions, false to just close the GUI
     */
    public boolean usePreviousScreenOnBack() {
        return true;
    }

    /**
     * Helper method to get the Minecraft Instance
     */
    public Minecraft getMinecraft() {
        return Minecraft.getInstance();
    }
}

package dev.ftb.mods.ftblibrary.client.gui.widget;

import dev.ftb.mods.ftblibrary.client.gui.IScreenWrapper;
import dev.ftb.mods.ftblibrary.client.gui.input.Key;
import dev.ftb.mods.ftblibrary.client.gui.input.MouseButton;
import dev.ftb.mods.ftblibrary.platform.Platform;
import dev.ftb.mods.ftblibrary.util.TooltipList;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.client.input.CharacterEvent;
import net.minecraft.client.input.KeyEvent;
import net.minecraft.client.input.MouseButtonEvent;
import net.minecraft.world.item.ItemStack;

import java.util.Optional;

public class ScreenWrapper extends Screen implements IScreenWrapper {
    private final BaseScreen wrappedGui;
    private final TooltipList tooltipList;

    public ScreenWrapper(BaseScreen wrappedGui) {
        super(wrappedGui.getTitle());

        this.wrappedGui = wrappedGui;
        tooltipList = new TooltipList();
    }

    @Override
    public void init() {
        super.init();
//		wrappedGui.itemRenderer = itemRenderer;
        wrappedGui.initGui();
    }

    @Override
    public boolean isPauseScreen() {
        return wrappedGui.doesGuiPauseGame();
    }

    @Override
    public boolean mouseClicked(MouseButtonEvent event, boolean flag) {
        wrappedGui.updateMouseOver((int) event.x(), (int) event.y());

        if (event.button() == MouseButton.BACK.id) {
            wrappedGui.onBack();
            return true;
        } else {
            return wrappedGui.mousePressed(MouseButton.get(event.button())) || super.mouseClicked(event, flag);
        }
    }

    @Override
    public boolean mouseReleased(MouseButtonEvent event) {
        wrappedGui.updateMouseOver((int) event.x(), (int) event.y());
        wrappedGui.mouseReleased(MouseButton.get(event.button()));
        return super.mouseReleased(event);
    }

    @Override
    public boolean mouseScrolled(double x, double y, double scrollX, double scrollY) {
        return wrappedGui.mouseScrolled(x, y, scrollX, scrollY) || super.mouseScrolled(x, y, scrollX, scrollY);
    }

    @Override
    public boolean mouseDragged(MouseButtonEvent mouseButtonEvent, double dragX, double dragY) {
        return wrappedGui.mouseDragged(mouseButtonEvent.button(), dragX, dragY) || super.mouseDragged(mouseButtonEvent, dragX, dragY);
    }

    @Override
    public boolean keyPressed(KeyEvent event) {
//        var key = new Key(event.key(), event.scancode(), event.modifiers(), event);

        var key = new Key(event);
        if (wrappedGui.keyPressed(key)) {
            return true;
        } else {
            if (key.backspace()) {
                wrappedGui.onBack();
                return true;
            } else if (wrappedGui.onClosedByKey(key)) {
                if (shouldCloseOnEsc()) {
                    wrappedGui.closeGui(true);
                }
                return true;
            } else if (Platform.get().isModLoaded("jei")) {
                wrappedGui.getIngredientUnderMouse().ifPresent(underMouse -> handleIngredientKey(key, underMouse.ingredient()));
            }

            return super.keyPressed(event);
        }
    }

    @Override
    public boolean keyReleased(KeyEvent event) {
        return wrappedGui.keyReleased(new Key(event)) || super.keyReleased(event);
    }

    @Override
    public boolean charTyped(CharacterEvent event) {
        return wrappedGui.charTyped(event) || super.charTyped(event);
    }

    private void handleIngredientKey(Key key, Object object) {
        //FIXME: FTBLibJEIIntegration.handleIngredientKey(key, object);
    }

    @Override
    public void extractRenderState(GuiGraphicsExtractor graphics, int mouseX, int mouseY, float partialTicks) {
        wrappedGui.updateGui(mouseX, mouseY, partialTicks);
        var x = wrappedGui.getX();
        var y = wrappedGui.getY();
        var w = wrappedGui.width;
        var h = wrappedGui.height;
        var theme = wrappedGui.getTheme();

        wrappedGui.draw(graphics, theme, x, y, w, h);
        wrappedGui.drawForeground(graphics, theme, x, y, w, h);
        wrappedGui.addMouseOverText(tooltipList);

        graphics.pose().pushMatrix();
        if (!tooltipList.shouldRender()) {
            wrappedGui.getIngredientUnderMouse().ifPresent(underMouse -> {
                if (underMouse.tooltip()) {
                    var ingredient = underMouse.ingredient();
                    if (ingredient instanceof ItemStack stack && !stack.isEmpty()) {
                        graphics.setTooltipForNextFrame(theme.getFont(), stack, mouseX, mouseY);
                    }
                }
            });
        } else {
            graphics.setTooltipForNextFrame(theme.getFont(), tooltipList.getLines(), Optional.empty(), mouseX, Math.max(mouseY, 18));
        }
        graphics.pose().popMatrix();

        tooltipList.reset();
    }

    @Override
    public void extractBackground(GuiGraphicsExtractor matrixStack, int x, int y, float partialTicks) {
        if (wrappedGui.drawDefaultBackground(matrixStack)) {
            super.extractBackground(matrixStack, x, y, partialTicks);
        }
    }

    @Override
    protected void extractBlurredBackground(GuiGraphicsExtractor guiGraphics) {
        if (wrappedGui.shouldRenderBlur()) {
            super.extractBlurredBackground(guiGraphics);
        }
    }

    @Override
    public void tick() {
        super.tick();
        wrappedGui.tick();
    }

    @Override
    public BaseScreen getGui() {
        return wrappedGui;
    }

    @Override
    public void removed() {
        wrappedGui.onClosed();
        super.removed();
    }

    @Override
    public boolean shouldCloseOnEsc() {
        return getGui().shouldCloseOnEsc();
    }
}

package dev.ftb.mods.ftblibrary.client.config.editable;

import dev.ftb.mods.ftblibrary.client.config.ConfigCallback;
import dev.ftb.mods.ftblibrary.client.config.gui.EditStringConfigOverlay;
import dev.ftb.mods.ftblibrary.client.gui.input.MouseButton;
import dev.ftb.mods.ftblibrary.client.gui.widget.BaseScreen;
import dev.ftb.mods.ftblibrary.client.gui.widget.Widget;
import net.minecraft.network.chat.Component;
import org.jspecify.annotations.Nullable;

import java.util.Optional;
import java.util.function.Consumer;

/**
 * A config value which can be parsed from a string, e.g. strings themselves, numeric values...
 * @param <T> the config value type
 */
public abstract class EditableStringifiedConfig<T> extends EditableConfigValue<T> {
    public abstract boolean parse(@Nullable Consumer<T> callback, String string);

    public String getStringFromValue(T v) {
        return String.valueOf(v);
    }

    @Override
    public Component getStringForGUI(T value) {
        return Component.literal(getStringFromValue(value));
    }

    @Override
    public void onClicked(Widget clicked, MouseButton button, ConfigCallback callback) {
        BaseScreen gui = clicked.getGui();

        EditStringConfigOverlay.PosProvider.Offset offset = clicked instanceof EditStringConfigOverlay.PosProvider p ?
                p.getOverlayOffset() :
                EditStringConfigOverlay.PosProvider.Offset.NONE;
        int xPos = clicked.getX() - gui.getX() + offset.x();
        int yPos = clicked.getY() - gui.getY() + offset.y();

        EditStringConfigOverlay<T> panel = new EditStringConfigOverlay<>(gui, this, callback);
        panel.setPos(xPos, yPos);
        gui.pushModalPanel(panel);
    }

    public boolean canScroll() {
        return false;
    }

    public Optional<T> scrollValue(T currentValue, boolean forward) {
        return Optional.empty();
    }

    protected boolean okValue(@Nullable Consumer<T> callback, T v) {
        if (callback != null) callback.accept(v);
        return true;
    }

    public int getExtraEditorWidth() {
        return 86;
    }
}

package dev.ftb.mods.ftblibrary.client.gui.widget;

public abstract class ModalPanel extends Panel {
    int extraZlevel = 1;

    public ModalPanel(Panel panel) {
        super(panel);
    }

    @Override
    public boolean checkMouseOver(int mouseX, int mouseY) {
        var ax = getX();
        var ay = getY();
        return mouseX >= ax && mouseY >= ay && mouseX < ax + width && mouseY < ay + height;
    }

    public int getExtraZlevel() {
        return extraZlevel;
    }

    public void setExtraZlevel(int extraZlevel) {
        this.extraZlevel = extraZlevel;
    }
}

package dev.ftb.mods.ftblibrary.config.manager;

import de.marhali.json5.Json5;
import dev.ftb.mods.ftblibrary.FTBLibrary;
import dev.ftb.mods.ftblibrary.client.config.EditableConfigGroup;
import dev.ftb.mods.ftblibrary.config.ConfigUtil;
import dev.ftb.mods.ftblibrary.config.serializer.Json5ConfigSerializer;
import dev.ftb.mods.ftblibrary.config.value.Config;
import dev.ftb.mods.ftblibrary.json5.Json5Util;
import dev.ftb.mods.ftblibrary.net.SyncConfigFromServerPacket;
import dev.ftb.mods.ftblibrary.platform.network.Server2PlayNetworking;
import it.unimi.dsi.fastutil.booleans.BooleanConsumer;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import org.jspecify.annotations.Nullable;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Function;

public enum ConfigManager {
    INSTANCE;

    final Map<String,TrackedConfig> pendingClient = new HashMap<>();
    final Map<String,TrackedConfig> pendingServer = new HashMap<>();

    // concurrent because startup configs can be loaded in mod construction threads
    private final Map<String, TrackedConfig> trackedConfigs = new ConcurrentHashMap<>();
    private boolean inited = false;

    public static ConfigManager getInstance() {
        return INSTANCE;
    }

    public void init() {
        if (inited) {
            throw new IllegalStateException("already initialised!");
        }

        inited = true;
    }

    /**
     * Register a client config.
     * @see #registerClientConfig(Config, String, BooleanConsumer)
     *
     * @param config the {@link Config} object, typically created by {@code ConfigGroup.create()}
     * @param groupPrefix a group prefix for translation purposes; should start with your mod ID
     * @return the same config object
     */
    public Config registerClientConfig(Config config, String groupPrefix) {
        return registerClientConfig(config, groupPrefix, TrackedConfig.NO_ACTION);
    }

    /**
     * Register a client config. Client configs are loaded on client setup, specifically when the NeoForge
     * {@code ClientStartedEvent} or Fabric  {@code ClientLifecycleEvents.CLIENT_STARTED} event is fired.
     * This method does not need to be called on the server, though it does not hurt to do so.
     *
     * @param config the {@link Config} object, typically statically created by {@link Config#create(String)}
     * @param groupPrefix a group prefix for translation purposes; should start with your mod ID
     * @param onEdited a BooleanConsumer which is called when the config is edited via GUI, or changed via sync from server
     * @return the same config object
     */
    public Config registerClientConfig(Config config, String groupPrefix, BooleanConsumer onEdited) {
        pendingClient.put(config.getKey(), TrackedConfig.createForRegistration(groupPrefix, ConfigType.CLIENT, config, false, onEdited));
        return config;
    }

    /**
     * @see #registerServerConfig(Config, String, boolean, BooleanConsumer)
     *
     * @param config the {@link Config} object, typically statically created by {@link Config#create(String)}
     * @param groupPrefix a group prefix for translation purposes; should start with your mod ID
     * @param sync if true, this config is automatically sync'd to clients when players log in
     * @return the same config object
     */
    public Config registerServerConfig(Config config, String groupPrefix, boolean sync) {
        return registerServerConfig(config, groupPrefix, sync, TrackedConfig.NO_ACTION);
    }

    /**
     * Register a server config. Server configs are loaded on server startup, specifically when the NeoForge
     * {@code ServerAboutToStartEvent} or the Fabric {@code ServerLifecycleEvents.SERVER_STARTING} event is fired.
     *
     * @param config the {@link Config} object, typically created by {@link Config#create(String)}
     * @param groupPrefix a group prefix for translation purposes; should start with your mod ID
     * @param sync if true, this config is automatically sync'd to clients when players log in
     * @param onEdited a BooleanConsumer which is called when the config is changed via sync from client
     *
     * @return the same config object
     */
    public Config registerServerConfig(Config config, String groupPrefix, boolean sync, BooleanConsumer onEdited) {
        pendingServer.put(config.getKey(), TrackedConfig.createForRegistration(groupPrefix, ConfigType.SERVER, config, sync, onEdited));
        return config;
    }

    /**
     * Register a startup config. Startup configs are loaded immediately, i.e. as soon as this method is called
     * (typically from the mod constructor). Startup configs are loaded on both client and server, not
     * synchronized, and not editable in-game. This should only be used for configuring the setup phase of mods,
     * before the client or server are ready for use.
     *
     * @param config the {@link Config} object, typically created by {@code ConfigGroup.create()}
     * @param groupPrefix a group prefix for translation purposes; should start with your mod ID
     */
    public Config registerStartupConfig(Config config, String groupPrefix) {
        var tc = TrackedConfig.createForRegistration(groupPrefix, ConfigType.SERVER, config, false, TrackedConfig.NO_ACTION);
        findAndLoad(config.getKey(), tc, ConfigUtil.LOCAL_DIR::resolve);
        return config;
    }

    public void save(String key) {
        TrackedConfig tc = trackedConfigs.get(key);
        if (tc == null) {
            throw new IllegalArgumentException("Unknown tracked config: " + key);
        }
        if (tc.loadedFrom == null) {
            throw new IllegalArgumentException("Tracked config " + key + " not fully initialised (trying to save before tracking?)");
        }

        try {
            Json5ConfigSerializer.writeToFile(tc.config, tc.loadedFrom);
            FTBLibrary.LOGGER.debug("saved config name={} path={}", key, tc.loadedFrom);
        } catch (IOException e) {
            FTBLibrary.LOGGER.error("failed to save config {}: {}", tc, e.getMessage());
        }
    }

    /**
     * Called when a server config is sync'd to the client on player login.
     *
     * @param serverConfigName name of the server config, expected to be registered on client
     * @param configData the config settings
     */
    public void syncFromServer(String serverConfigName, String configData) {
        TrackedConfig tc = trackedConfigs.get(serverConfigName);
        if (tc != null) {
            tc.config.read(new Json5ConfigSerializer(new Json5().parse(configData).getAsJson5Object()));
            tc.onEdited.accept(false);
            FTBLibrary.LOGGER.info("received server config settings for config: {}", serverConfigName);
        } else {
            FTBLibrary.LOGGER.error("received unknown config name {} from server!", serverConfigName);
        }
    }

    /**
     * Called when a player applies changes to a server config via GUI.
     *
     * @param serverConfigName name of the server config, expected to be registered on server
     * @param configData the config settings
     * @param playerName player who made the changes
     */
    public void syncFromClient(String serverConfigName, String configData, String playerName) {
        TrackedConfig tc = trackedConfigs.get(serverConfigName);
        if (tc != null) {
            tc.config.read(new Json5ConfigSerializer(new Json5().parse(configData).getAsJson5Object()));
            tc.onEdited.accept(true);
            save(serverConfigName);
            FTBLibrary.LOGGER.info("received client config settings from {} for config: {}", playerName, serverConfigName);
        } else {
            FTBLibrary.LOGGER.error("player {} tried to sync an unknown config {} from client!", playerName, serverConfigName);
        }
    }

    public void onServerStarting(MinecraftServer server) {
        pendingServer.forEach((key, config) ->
                findAndLoad(key, config, fileName -> server.getWorldPath(ConfigUtil.SERVER_CONFIG_DIR).resolve(fileName))
        );
        pendingServer.clear();
    }

    public void onPlayerLogin(ServerPlayer serverPlayer) {
        trackedConfigs.values().forEach(tc -> {
            if (tc.synced) {
                Server2PlayNetworking.send(serverPlayer, SyncConfigFromServerPacket.create(tc.config));
            }
        });
    }

    void findAndLoad(String key, TrackedConfig protoTc, Function<String, Path> overridePathSupplier) {
        String fileName = key + Json5Util.FILE_EXT;

        Path primaryPath = ConfigUtil.CONFIG_DIR.resolve(fileName);
        Path overridePath = overridePathSupplier.apply(fileName);

        if (Files.exists(overridePath)) {
            // an override exists in .../<world>/serverconfig/<name>.snbt, use that
            loadAndTrack(key, protoTc, overridePath);
        } else {
            // no override; just load the config from the primary config path: .../config/<name>.snbt
            loadAndTrack(key, protoTc, primaryPath);
        }
    }

    private void loadAndTrack(String key, TrackedConfig protoTc, Path path) {
        try {
            Json5ConfigSerializer.readFromFile(protoTc.config, path);
            startTracking(key, protoTc.promoteToFull(path));
        } catch (IOException e) {
            FTBLibrary.LOGGER.error("can't read config {} from {}: {}/{}", key, path, e.getClass().getName(), e.getMessage());
        }
    }

    void startTracking(String key, TrackedConfig trackedConfig) {
        trackedConfigs.put(key, trackedConfig);
        FTBLibrary.LOGGER.debug("tracking config {}, loaded from {}", key, trackedConfig.loadedFrom);
    }

    public void editedOnClient(String key) {
        TrackedConfig tc = trackedConfigs.get(key);
        if (tc != null) {
            tc.onEdited.accept(false);
        }
    }

    /**
     * Create an editable ConfigGroup for this config, suitable for passing to EditConfigScreen.
     *
     * @param configName the config name, as previously registered
     * @return a ConfigGroup object, or {@code Optional.empty()} if the config is not known or is a startup config
     */
    public Optional<EditableConfigGroup> createConfigGroup(String configName) {
        TrackedConfig tc = trackedConfigs.get(configName);
        return tc != null && tc.configType != ConfigType.STARTUP ?
                Optional.of(ConfigUtil.makeConfigEditGroup(tc.config, tc.groupPrefix, tc.configType == ConfigType.SERVER)) :
                Optional.empty();
    }

    /**
     * A config plus information about its file path, sync status etc.
     *
     * @param loadedFrom path the config has been loaded from
     * @param config     the config itself
     * @param synced     true if a server config which is sync'd to clients, false otherwise
     * @param onEdited   a BooleanConsumer called when config has been edited;
     *                   receives true if server-side (i.e. config received from client after GUI editing),
     *                   false if client-side (i.e. config has just been edited via GUI)
     */
    record TrackedConfig(@Nullable Path loadedFrom, ConfigType configType, Config config, boolean synced, BooleanConsumer onEdited, String groupPrefix) {
        static final BooleanConsumer NO_ACTION = isServer -> {};

        /**
         * Created client-side for server configs which are sync'd to the client. No file path since server configs
         * are never saved to disk on the client.
         *
         * @return the client-side mirror of a server config
         */
        TrackedConfig clientMirrorOfServerConfig() {
            return new TrackedConfig(null, ConfigType.SERVER, config, false, onEdited, groupPrefix);
        }

        /**
         * Proto-tracked-config created during registration, before the actual file path is known.
         * @param config the config object
         * @param sync true if server config that is sync'd to client
         * @param onChanged called when config is changed
         * @return a new proto-tracked-config object
         */
        static TrackedConfig createForRegistration(String groupPrefix, ConfigType configType, Config config, boolean sync, BooleanConsumer onChanged) {
            return new TrackedConfig(null, configType, config, sync, onChanged, groupPrefix);
        }

        /**
         * Promotes a proto-tracked-config to a full one when the config is actually loaded from disk.
         *
         * @param path the load path
         * @return a new, full, tracked config
         */
        TrackedConfig promoteToFull(Path path) {
            return new TrackedConfig(path, configType, config, synced, onEdited, groupPrefix);
        }
    }

    enum ConfigType {
        SERVER,
        CLIENT,
        STARTUP
    }
}

package dev.ftb.mods.ftblibrary.config;

import dev.ftb.mods.ftblibrary.client.config.EditableConfigGroup;
import dev.ftb.mods.ftblibrary.client.config.gui.EditConfigScreen;
import dev.ftb.mods.ftblibrary.config.value.Config;
import dev.ftb.mods.ftblibrary.platform.Platform;
import net.minecraft.util.Util;
import net.minecraft.world.level.storage.LevelResource;

import java.nio.file.Path;

public interface ConfigUtil {
    Path ROOT_DIR = Platform.get().paths().gamePath();

    Path DEFAULT_CONFIG_DIR = ROOT_DIR.resolve("defaultconfigs");
    Path CONFIG_DIR = Platform.get().paths().configPath();
    Path LOCAL_DIR = ROOT_DIR.resolve("local");

    LevelResource SERVER_CONFIG_DIR = new LevelResource("serverconfig");

    /**
     * Create a {@link EditableConfigGroup} object, suitable for passing as a parameter to the
     * {@link EditConfigScreen} constructor.
     *
     * @param config the config to be edited
     * @param groupName the config group name, which is the top-level path for objects in this group (used primarily for translations)
     * @param isServerConfig if true, config is sync'd to server after editing; if false, config is saved locally on client
     * @return a new config group object
     */
    static EditableConfigGroup makeConfigEditGroup(Config config, String groupName, boolean isServerConfig) {
        return Util.make(EditableConfigGroup.createEditable(config, groupName, isServerConfig), config::addToEditableConfigGroup);
    }
}

