import dev.ftb.mods.ftblibrary.client.gui.theme.Theme;
import dev.ftb.mods.ftblibrary.icon.Color4I;
import dev.ftb.mods.ftblibrary.icon.Icon;
import dev.ftb.mods.ftblibrary.icon.Icons;
import net.minecraft.network.chat.Component;

public class EditableBoolean extends EditableVariantConfig<Boolean> {
    public static final Component TRUE_TEXT = Component.literal("True");
    public static final Component FALSE_TEXT = Component.literal("False");

    @Override
    public Color4I getColor(Boolean value, Theme theme) {
        return Tristate.ofBoolean(value).getColor(theme);
    }

    @Override
    public Boolean getIteration(Boolean currentValue, boolean next) {
        return !currentValue;
    }

    @Override
    public Component getStringForGUI(Boolean value) {
        return value ? TRUE_TEXT : FALSE_TEXT;
    }

    @Override
    public Icon<?> getIcon(Boolean value) {
        return value ? Icons.ACCEPT : Icons.ACCEPT_GRAY;
    }
}

package dev.ftb.mods.ftblibrary.net;

import dev.ftb.mods.ftblibrary.FTBLibrary;
import dev.ftb.mods.ftblibrary.config.manager.ConfigManager;
import dev.ftb.mods.ftblibrary.config.serializer.Json5ConfigSerializer;
import dev.ftb.mods.ftblibrary.config.value.Config;
import dev.ftb.mods.ftblibrary.platform.network.PacketContext;
import dev.ftb.mods.ftblibrary.platform.network.Server2PlayNetworking;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.server.permissions.Permissions;

public record SyncConfigToServerPacket(String configName, String config) implements CustomPacketPayload {
    public static final Type<SyncConfigToServerPacket> TYPE = new Type<>(FTBLibrary.id("sync_config_to_server_packet"));

    public static final StreamCodec<FriendlyByteBuf, SyncConfigToServerPacket> STREAM_CODEC = StreamCodec.composite(
            ByteBufCodecs.STRING_UTF8, SyncConfigToServerPacket::configName,
            ByteBufCodecs.STRING_UTF8, SyncConfigToServerPacket::config,
            SyncConfigToServerPacket::new
    );

    public static SyncConfigToServerPacket create(Config config) {
        return new SyncConfigToServerPacket(config.getKey(), Json5ConfigSerializer.serialize(config).toString());
    }

    @Override
    public Type<SyncConfigToServerPacket> type() {
        return TYPE;
    }

    public static void handle(SyncConfigToServerPacket message, PacketContext context) {
        if (context.player() instanceof ServerPlayer sp && sp.permissions().hasPermission(Permissions.COMMANDS_OWNER)) {
            context.enqueue(() -> {
                MinecraftServer server = sp.level().getServer();

                ConfigManager.getInstance().syncFromClient(message.configName, message.config, sp.getGameProfile().name());

                // send the updated config to all other players
                for (ServerPlayer player : server.getPlayerList().getPlayers()) {
                    if (!sp.getUUID().equals(player.getUUID())) {
                        Server2PlayNetworking.send(player, new SyncConfigFromServerPacket(message.configName, message.config));
                    }
                }
            });
        }
    }
}

package dev.ftb.mods.ftblibrary.net;

import dev.ftb.mods.ftblibrary.FTBLibrary;
import dev.ftb.mods.ftblibrary.client.config.gui.ChooseConfigScreen;
import dev.ftb.mods.ftblibrary.config.manager.ConfigManagerClient;
import dev.ftb.mods.ftblibrary.platform.network.PacketContext;
import dev.ftb.mods.ftblibrary.util.NetworkHelper;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.ComponentSerialization;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.server.permissions.Permissions;

public record EditConfigChoicePacket(ConfigType configType, String clientConfig, String serverConfig, Component title) implements CustomPacketPayload {
    public static final CustomPacketPayload.Type<EditConfigChoicePacket> TYPE = new CustomPacketPayload.Type<>(FTBLibrary.id("edit_config_choice_packet"));

    public static final StreamCodec<RegistryFriendlyByteBuf, EditConfigChoicePacket> STREAM_CODEC = StreamCodec.composite(
            NetworkHelper.enumStreamCodec(ConfigType.class), EditConfigChoicePacket::configType,
            ByteBufCodecs.STRING_UTF8, EditConfigChoicePacket::clientConfig,
            ByteBufCodecs.STRING_UTF8, EditConfigChoicePacket::serverConfig,
            ComponentSerialization.STREAM_CODEC, EditConfigChoicePacket::title,
            EditConfigChoicePacket::new
    );

    @Override
    public CustomPacketPayload.Type<EditConfigChoicePacket> type() {
        return TYPE;
    }

    public static EditConfigChoicePacket choose(String clientConfig, String serverConfig, Component title) {
        return new EditConfigChoicePacket(ConfigType.CHOOSE, clientConfig, serverConfig, title);
    }

    public static EditConfigChoicePacket client(String clientConfig) {
        return new EditConfigChoicePacket(ConfigType.CLIENT, clientConfig, "", Component.empty());
    }

    public static EditConfigChoicePacket server(String serverConfig) {
        return new EditConfigChoicePacket(ConfigType.SERVER, "", serverConfig, Component.empty());
    }

    public static void handle(EditConfigChoicePacket message, PacketContext context) {
        switch (message.configType) {
            case CLIENT -> ConfigManagerClient.editConfig(message.clientConfig);
            case SERVER -> {
                if (context.player().permissions().hasPermission(Permissions.COMMANDS_OWNER)) {
                    ConfigManagerClient.editConfig(message.serverConfig());
                }
            }
            case CHOOSE -> {
                if (context.player().permissions().hasPermission(Permissions.COMMANDS_OWNER)) {
                    ChooseConfigScreen.open(message);
                } else {
                    ConfigManagerClient.editConfig(message.clientConfig());
                }
            }
        }
    }

    public enum ConfigType {
        CLIENT,
        SERVER,
        CHOOSE
    }
}

