package dev.ftb.mods.ftblibrary.config.value;

import dev.ftb.mods.ftblibrary.client.config.EditableConfigGroup;
import dev.ftb.mods.ftblibrary.client.config.editable.EditableConfigValue;
import dev.ftb.mods.ftblibrary.config.serializer.ConfigSerializer;
import dev.ftb.mods.ftblibrary.util.NameMap;
import org.jspecify.annotations.Nullable;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * A {@code Config} is basically a list of values of any {@link BaseValue} type, including another
 * {@code Config}, allowing for nested config groups.
 */
public class Config extends BaseValue<List<BaseValue<?>>> {
    private int displayOrder = 0;

    private Config(@Nullable Config parent, String key, List<BaseValue<?>> defaultValue) {
        super(parent, key, defaultValue);
    }

    /**
     * Create a new config object
     *
     * @param key the name for the config, typically something like "{modid}-client" or "{modid}-server"
     * @return the new config object
     */
    public static Config create(String key) {
        return new Config(null, key, new ArrayList<>());
    }

    @Override
    public void write(ConfigSerializer serializer) {
        serializer.putConfigSection(key, this, parent == null);
    }

    @Override
    public void read(ConfigSerializer serializer) {
        set(serializer.getConfigSection(key, defaultValue, parent == null));
    }

    @Override
    @Nullable
    protected EditableConfigValue<?> fillClientConfig(EditableConfigGroup group) {
        List<BaseValue<?>> sorted = defaultValue.stream()
                .filter(v -> !v.excluded)
                .sorted(Comparator.comparingInt(o -> o.displayOrder))
                .toList();

        var actualGroup = parent == null ? group : group.getOrCreateSubgroup(key, displayOrder);
        sorted.forEach(value -> value.addToEditableConfigGroup(actualGroup));

        return null;
    }

    public <T extends BaseValue<?>> T add(T value) {
        defaultValue.add(value);
        return value;
    }

    public Config addGroup(String key) {
        return addGroup(key, 0);
    }

    public Config addGroup(String key, int displayOrder) {
        Config value = new Config(this, key, new ArrayList<>());
        value.displayOrder = displayOrder;
        return add(value);
    }

    public BooleanValue addBoolean(String key, boolean defaultValue) {
        return add(new BooleanValue(this, key, defaultValue));
    }

    public IntValue addInt(String key, int defaultValue) {
        return add(new IntValue(this, key, defaultValue));
    }

    public IntValue addInt(String key, int defaultValue, int min, int max) {
        return addInt(key, defaultValue).range(min, max);
    }

    public LongValue addLong(String key, long defaultValue) {
        return add(new LongValue(this, key, defaultValue));
    }

    public LongValue addLong(String key, long defaultValue, long min, long max) {
        return addLong(key, defaultValue).range(min, max);
    }

    public DoubleValue addDouble(String key, double defaultValue) {
        return add(new DoubleValue(this, key, defaultValue));
    }

    public DoubleValue addDouble(String key, double def, double min, double max) {
        return addDouble(key, def).range(min, max);
    }

    public StringValue addString(String key, String defaultValue) {
        return add(new StringValue(this, key, defaultValue));
    }

    public StringListValue addStringList(String key, List<String> defaultValue) {
        return add(new StringListValue(this, key, defaultValue));
    }

    public <T> EnumValue<T> addEnum(String key, NameMap<T> nameMap) {
        return add(new EnumValue<>(this, key, nameMap));
    }

    public <T> EnumValue<T> addEnum(String key, NameMap<T> nameMap, T defaultValue) {
        return add(new EnumValue<>(this, key, nameMap, defaultValue));
    }

    public IntArrayValue addIntArray(String key, int[] defaultValue) {
        return add(new IntArrayValue(this, key, defaultValue));
    }
}

package dev.ftb.mods.ftblibrary.client.config.editable;

import dev.ftb.mods.ftblibrary.client.config.ConfigCallback;
import dev.ftb.mods.ftblibrary.client.gui.input.MouseButton;
import dev.ftb.mods.ftblibrary.client.gui.widget.Widget;

/**
 * A config value with some well-defined options, which can be cycled through.
 */
public abstract class EditableVariantConfig<T> extends EditableConfigValue<T> {
    /**
     * Get the next (or previous) valid value for this config item.
     * @param currentValue the current value
     * @param next true to get the next value, false to get the previous value
     * @return the next or previous valid value, as appropriate
     */
    public abstract T getIteration(T currentValue, boolean next);

    @Override
    public void onClicked(Widget clickedWidget, MouseButton button, ConfigCallback callback) {
        boolean changed = updateValue(getIteration(value, button.isLeft()));
        callback.save(changed);
    }
}

package dev.ftb.mods.ftblibrary.config.value;

import dev.ftb.mods.ftblibrary.client.config.EditableConfigGroup;
import dev.ftb.mods.ftblibrary.client.config.editable.EditableConfigValue;
import dev.ftb.mods.ftblibrary.config.serializer.ConfigSerializer;
import dev.ftb.mods.ftblibrary.json5.Json5Util;
import dev.ftb.mods.ftblibrary.util.Lambdas;
import org.jspecify.annotations.Nullable;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.function.BooleanSupplier;

/**
 * Top-level class for all config values
 *
 * @param <T> the value's type
 */
public abstract class BaseValue<T> implements Comparable<BaseValue<T>> {
    @Nullable
    protected final Config parent;
    protected final String key;
    protected final T defaultValue;
    protected boolean excluded;
    protected BooleanSupplier enabled = Lambdas.ALWAYS_TRUE;
    protected int displayOrder = 0;
    protected List<String> comment = new ArrayList<>(0);
    private T value;

    protected BaseValue(@Nullable Config parent, String key, T defaultValue) {
        this.parent = parent;
        this.key = key;
        this.defaultValue = defaultValue;
        value = this.defaultValue;
    }

    @Override
    public String toString() {
        if (parent == null) {
            return key;
        }

        return parent + "/" + key;
    }

    public String getKey() {
        return key;
    }

    public T get() {
        return value;
    }

    public void set(T v) {
        value = v;
    }

    /**
     * Add a (possibly multiline) comment for this config value. This comment will appear with the value in the saved
     * config file, along with possible information about the value (e.g. acceptable value, range, etc.)
     *
     * @param comment the comment text, one string per line
     * @return the value itself, for fluency
     */
    public <E extends BaseValue<T>> E comment(String... comment) {
        this.comment.addAll(Arrays.asList(comment));
        return self();
    }

    /**
     * Add a standard top-level comment. Useful for the majority of configs.
     *
     * @param modName the mod's display name
     * @param key the config key which was passed to {@link Config#create(String)}
     * @param forClient true if this is a client config, false if server config
     * @param extraLines any extra text you may wish to add
     * @return the value itself, for fluency
     */
    public <E extends BaseValue<T>> E standardTopLevelComment(String modName, String key, boolean forClient, String... extraLines) {
        String filename = key + Json5Util.FILE_EXT;
        List<String> txt = forClient ?
                List.of(
                        "Client-specific configuration for " + modName,
                        "Modpack defaults should be defined in <instance>/config/" + filename,
                        "  (may be overwritten on modpack update)",
                        "Players may locally override this by copying into <instance>/local/" + filename,
                        "  (will NOT be overwritten on modpack update)"
                ) :
                List.of(
                        "Server-specific configuration for " + modName,
                        "Modpack defaults should be defined in <instance>/config/" + filename,
                        "  (may be overwritten on modpack update)",
                        "Server admins may locally override this by copying into <instance>/world/serverconfig/" + filename,
                        "  (will NOT be overwritten on modpack update)"
                );

        comment.addAll(txt);
        comment.addAll(Arrays.asList(extraLines));

        return self();
    }

    /**
     * Mark this config value as being excluded from GUI config editing, even the value's type is normally editable.
     * This can be used for values that may be managed automatically, where direct player editing is undesirable.
     *
     * @return the value itself, for fluency
     */
    public <E extends BaseValue<T>> E excludedFromGui() {
        excluded = true;
        return self();
    }

    /**
     * Specify a predicate to control whether this config value is enabled for editing in the config GUI. Entries which
     * are disabled appear greyed out in the GUI and can't be changed interactively, but their values are still
     * readable and writable via API.
     *
     * @param enabled the predicate
     * @return the value itself, for fluency
     */
    public <E extends BaseValue<T>> E enabledForEdit(BooleanSupplier enabled) {
        this.enabled = enabled;
        return self();
    }

    /**
     * Specify a display order for this entry to control its ordering within its config section in the GUI. By default,
     * all entries have an ordering of 0. Entries with the same order are sorted alphabetically by their display text.
     *
     * @param order the ordering
     * @return the value itself, for fluency
     */
    public <E extends BaseValue<T>> E withDisplayOrder(int order) {
        this.displayOrder = order;
        return self();
    }

    protected <E extends BaseValue<T>> E self() {
        //noinspection unchecked
        return (E) this;
    }

    public abstract void write(ConfigSerializer serializer);

    public abstract void read(ConfigSerializer serializer);

    private int getOrder() {
        return this instanceof Config ? 1 : 0;
    }

    @Override
    public int compareTo(BaseValue<T> other) {
        var i = Integer.compare(getOrder(), other.getOrder());
        return i == 0 ? key.compareToIgnoreCase(other.key) : i;
    }

    public final void addToEditableConfigGroup(EditableConfigGroup group) {
        var editable = fillClientConfig(group);
        if (editable != null) {
            editable.setCanEdit(enabled);
        }
    }

    /**
     * Called when a client-side EditableConfigGroup is being created via
     * {@link dev.ftb.mods.ftblibrary.config.manager.ConfigManagerClient#editConfig(String)}. Implementations should
     * add a suitable {@link EditableConfigValue} field to the given config group for this config value (many
     * convenience methods exist in {@code ConfigGroup} for this).
     * <p>
     * This method should, of course, only be called on the client.
     *
     * @param group the config group being filled out
     * @return the editable field that was added, or null if this type isn't editable in the config GUI
     */
    @Nullable
    protected EditableConfigValue<?> fillClientConfig(EditableConfigGroup group) {
        return null;
    }

    /**
     * Override this method to add extra information about this config value type. This information will be included
     * in comments in the saved config file.
     *
     * @param header the header list to add lines to
     */
    protected void addExtraHeaderInfo(List<String> header) {
    }

    @Nullable
    public final String getCommentString() {
        List<String> c = new ArrayList<>(comment);
        addExtraHeaderInfo(c);
        return c.isEmpty() ? null : String.join("\n", c);
    }
}

package dev.ftb.mods.ftblibrary.config.serializer;

import com.mojang.serialization.Codec;
import de.marhali.json5.*;
import dev.ftb.mods.ftblibrary.FTBLibrary;
import dev.ftb.mods.ftblibrary.config.value.*;
import dev.ftb.mods.ftblibrary.json5.Json5Ops;
import dev.ftb.mods.ftblibrary.util.NameMap;
import net.minecraft.util.Util;

import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;
import java.util.function.Function;

public record Json5ConfigSerializer(Json5Object configJson) implements ConfigSerializer {
    public static Json5Object serialize(Config config) {
        Json5ConfigSerializer serializer = new Json5ConfigSerializer(new Json5Object());
        config.write(serializer);
        return serializer.configJson;
    }

    public static void readFromFile(Config config, Path path) throws IOException {
        if (!Files.exists(path)) {
            FTBLibrary.LOGGER.info("creating new default config file at {}", path);
            writeToFile(config, path);
        }
        try (FileInputStream input = new FileInputStream(path.toFile())) {
            var element = new Json5().parse(input);
            config.read(new Json5ConfigSerializer(element.getAsJson5Object()));
            writeToFile(config, path);
        } catch (FileNotFoundException | IllegalStateException e) {
            throw new IOException(e);
        }
    }

    public static void writeToFile(Config config, Path path) throws IOException {
        Files.createDirectories(path.getParent());
        Files.writeString(path, new Json5().serialize(serialize(config)));
    }

    @Override
    public List<BaseValue<?>> getConfigSection(String key, List<BaseValue<?>> defVal, boolean topLevel) {
        if (topLevel) {
            return readFromJson(configJson, defVal);
        } else if (configJson.has(key)) {
            return readFromJson(configJson.getAsJson5Object(key), defVal);
        } else {
            return List.of();
        }
    }

    private List<BaseValue<?>> readFromJson(Json5Object json, List<BaseValue<?>> defVal) {
        Json5ConfigSerializer serializer = new Json5ConfigSerializer(json);

        List<BaseValue<?>> res = new ArrayList<>();
        for (var value : defVal) {
            if (json.has(value.getKey())) {
                value.read(serializer);
            }
            res.add(value);
        }
        return res;
    }

    @Override
    public void putConfigSection(String key, Config val, boolean topLevel) {
        if (topLevel) {
            configJson.setComment(val.getCommentString());
            writeToJson(val.get(), configJson);
        } else {
            configJson.add(key, writeToJson(val.get(), Util.make(new Json5Object(), json -> json.setComment(val.getCommentString()))));
        }
    }

    private Json5Object writeToJson(List<BaseValue<?>> values, Json5Object json) {
        Json5ConfigSerializer serializer = new Json5ConfigSerializer(json);

        values.stream().sorted().toList().forEach(value -> value.write(serializer));

        return json;
    }

    @Override
    public boolean getBoolean(String key, boolean defVal) {
        return getPrimitive(configJson, key, Json5Primitive::getAsBoolean, defVal);
    }

    @Override
    public void putBoolean(String key, BooleanValue val) {
        configJson.add(key, makeCommentedPrimitive(val, Json5Primitive::fromBoolean));
    }

    @Override
    public double getDouble(String key, double defVal) {
        return getPrimitive(configJson, key, Json5Primitive::getAsDouble, defVal);
    }

    @Override
    public void putDouble(String key, DoubleValue val) {
        configJson.add(key, makeCommentedPrimitive(val, Json5Primitive::fromNumber));
    }

    @Override
    public int getInt(String key, int defVal) {
        return getPrimitive(configJson, key, Json5Primitive::getAsInt, defVal);
    }

    @Override
    public void putInt(String key, IntValue val) {
        configJson.add(key, makeCommentedPrimitive(val, Json5Primitive::fromNumber));
    }

    @Override
    public long getLong(String key, long defVal) {
        return getPrimitive(configJson, key, Json5Primitive::getAsLong, defVal);
    }

    @Override
    public void putLong(String key, LongValue val) {
        configJson.add(key, makeCommentedPrimitive(val, Json5Primitive::fromNumber));
    }

    @Override
    public <T> List<T> getList(String key, List<T> defVal, Codec<T> codec) {
        if (configJson.get(key) instanceof Json5Array array) {
            return Util.make(new ArrayList<>(),
                    list -> array.asList().forEach(el -> codec.parse(Json5Ops.INSTANCE, el).ifSuccess(list::add))
            );
        }
        return defVal;
    }

    @Override
    public <T> void putList(String key, AbstractListValue<T> val, Codec<T> codec) {
        configJson.add(key, Util.make(new Json5Array(val.get().size()), a -> {
                    a.setComment(val.getCommentString());
                    val.get().forEach(el -> codec.encodeStart(Json5Ops.INSTANCE, el).ifSuccess(a::add));
                })
        );
    }

    @Override
    public <T> Map<String, T> getMap(String key, Map<String, T> defVal, Codec<T> codec) {
        try {
            Map<String,T> res = new HashMap<>();
            configJson.getAsJson5Object(key).asMap().forEach((k, v) ->
                    codec.parse(Json5Ops.INSTANCE, v).ifSuccess(s -> res.put(k, s))
            );
            return res;
        } catch (ClassCastException e) {
            return defVal;
        }
    }

    @Override
    public <T> void putMap(String key, AbstractMapValue<T> val, Codec<T> codec) {
        configJson.add(key, Util.make(new Json5Object(), o -> {
            o.setComment(val.getCommentString());
            val.get().forEach((k, v) -> codec.encodeStart(Json5Ops.INSTANCE, v).ifSuccess(el -> o.add(k, el)));
        }));
    }

    @Override
    public String getString(String key, String defVal) {
        return getPrimitive(configJson, key, Json5Primitive::getAsString, defVal);
    }

    @Override
    public void putString(String key, StringValue val) {
        configJson.add(key, makeCommentedPrimitive(val, Json5Primitive::fromString));
    }

    @Override
    public int[] getIntArray(String key, int[] defVal) {
        try {
            return configJson.getAsJson5Array(key).asList().stream().map(Json5Element::getAsInt).mapToInt(i -> i).toArray();
        } catch (Exception ignored) {
        }
        return defVal;
    }

    @Override
    public void putIntArray(String key, IntArrayValue val) {
        configJson.add(key, Util.make(new Json5Array(val.get().length), a -> {
            a.setComment(val.getCommentString());
            Arrays.stream(val.get()).forEach(a::add);
        }));
    }

    @Override
    public <E> E getEnum(String key, E defVal, NameMap<E> nameMap) {
        try {
            return nameMap.get(configJson.getAsJson5Primitive(key).getAsString());
        } catch (ClassCastException ignored) {
            return defVal;
        }
    }

    @Override
    public <E> void putEnum(String key, EnumValue<E> val, NameMap<E> nameMap) {
        Json5Primitive strProp = Json5Primitive.fromString(nameMap.getName(val.get()));
        strProp.setComment(val.getCommentString());
        configJson.add(key, strProp);
    }

    private static <T> T getPrimitive(Json5Object json5Object, String key, Function<Json5Primitive,T> func, T defVal) {
        if (json5Object.get(key) instanceof Json5Primitive primitive) {
            try {
                return func.apply(primitive);
            } catch (ClassCastException | NumberFormatException ignored) {
            }
        }
        return defVal;
    }

    private static <T> Json5Primitive makeCommentedPrimitive(BaseValue<T> val, Function<T, Json5Primitive> func) {
        return Util.make(func.apply(val.get()), p -> p.setComment(val.getCommentString()));
    }

}

