public class TextBox extends Widget implements IFocusableWidget {
    public int charLimit = 2000;
    public Color4I textColor = Icon.empty();
    public String ghostText = "";
    private boolean isFocused = false;
    private String text = "";
    private int displayPos;
    private int cursorPos;
    private int highlightPos;
    private boolean validText = true;
    private int maxLength = 1024;
    private Predicate<String> filter;
    private Component label;
    private Color4I labelColor = Color4I.WHITE;
    private boolean strictValidity = false;

    public TextBox(Panel panel) {
        super(panel);

        this.filter = Objects::nonNull;
    }

    public void setMaxLength(int maxLength) {
        this.maxLength = maxLength;
    }

    @Override
    public void setWidth(int v) {
        super.setWidth(v);

        // force a recalc of displayPos, since it's dependent on the widget width
        scrollTo(getCursorPos());
    }

    @Override
    public final boolean isFocused() {
        return isFocused;
    }

    @Override
    public final void setFocused(boolean focused) {
        if (isFocused != focused) {
            isFocused = focused;
            if (focused) {
                getGui().setFocusedWidget(this);
            }
        }
    }

    public void setStrictValidity(boolean strictValidity) {
        this.strictValidity = strictValidity;
    }

    public void setFilter(Predicate<String> filter) {
        this.filter = filter;
    }

    public void setLabel(Component label) {
        this.label = label;
    }

    public void setLabelColor(Color4I color) {
        this.labelColor = color;
    }

    public final String getText() {
        return text;
    }

    public final void setText(String s) {
        setText(s, true);
    }

    public String getSelectedText() {
        return text.substring(Math.min(cursorPos, highlightPos), Math.max(cursorPos, highlightPos));
    }

    public void setText(String string, boolean triggerChange) {
        if (filter.test(string)) {
            if (string.length() > maxLength) {
                text = string.substring(0, maxLength);
            } else {
                text = string;
            }

            validText = isValid(text);

            moveCursorToEnd(false);
            setSelectionPos(cursorPos);
            if (triggerChange) {
                onTextChanged();
            }
        }
    }

    public boolean isValid(String txt) {
        return filter.test(txt);
    }

    public final boolean isTextValid() {
        return validText;
    }

    @Override
    public CursorType getCursor() {
        return CursorType.IBEAM;
    }
}

public class FTBLibrary {
    public static final String MOD_ID = "ftblibrary";
    public static final String MOD_NAME = "FTB Library";
    public static final Logger LOGGER = LogManager.getLogger(MOD_NAME);

    public FTBLibrary() {
        ConfigManager cfgMgr = ConfigManager.getInstance();
        cfgMgr.init();
        cfgMgr.registerClientConfig(FTBLibraryClientConfig.CONFIG, MOD_ID + ".client_settings");
        if (ModUtils.isDevMode()) {
            cfgMgr.registerStartupConfig(FTBLibraryStartupConfig.CONFIG, MOD_ID + ".startup_settings");
            cfgMgr.registerServerConfig(FTBLibraryServerConfig.CONFIG, MOD_ID + ".server_settings", true, FTBLibraryServerConfig::onChanged);
        }

        FTBLibraryNet.register();
        ModItems.init();

        ExtendableTextColor.addCustomColor("ftb:rainbow", RainbowTextColor.INSTANCE);
    }

@Nullable
@SuppressWarnings("unchecked")
public static <T> T getGuiAs(Screen gui, Class<T> clazz) {
    if (gui instanceof IScreenWrapper wrapper) {
        var guiBase = wrapper.getGui();
        if (clazz.isAssignableFrom(guiBase.getClass())) {
            return (T) guiBase;
        }
    }

    return clazz.isAssignableFrom(gui.getClass()) ? (T) Minecraft.getInstance().screen : null;
}

@Nullable
public static <T> T getCurrentGuiAs(Class<T> clazz) {
    return Minecraft.getInstance().screen == null ? null : getGuiAs(Minecraft.getInstance().screen, clazz);
}
